// kiro-power-v2.js
const fs=require('fs');const path=require('path');const{execSync}=require('child_process');
const files={"backend/src/services/kai.commands.service.ts":"// KIRO Quick Commands - power user shortcuts\n// Type / in chat to access these instantly\n\nimport { prisma } from \"../config/database\";\n\nexport interface QuickCommand {\n  command: string;\n  label: string;\n  description: string;\n  icon: string;\n  category: \"sales\" | \"products\" | \"marketing\" | \"analytics\" | \"operations\";\n  prompt: string;  // What KIRO does when triggered\n  requiresInput?: boolean;\n  inputLabel?: string;\n}\n\nexport const QUICK_COMMANDS: QuickCommand[] = [\n  // SALES\n  {\n    command: \"/flash-sale\",\n    label: \"Run Flash Sale\",\n    description: \"Launch a time-limited flash sale across products\",\n    icon: \"Zap\",\n    category: \"sales\",\n    prompt: \"Help me launch a flash sale. Suggest which products to discount based on inventory and sales velocity, then create the flash sale with optimal pricing for maximum urgency.\",\n  },\n  {\n    command: \"/discount\",\n    label: \"Create Discount Code\",\n    description: \"Generate a discount code with smart pricing\",\n    icon: \"Tag\",\n    category: \"sales\",\n    prompt: \"Create a smart discount code for my store. Suggest a code name and discount percentage based on my margins.\",\n    requiresInput: true,\n    inputLabel: \"What's the occasion? (e.g. weekend, first-time buyer)\",\n  },\n  {\n    command: \"/bogo\",\n    label: \"Buy One Get One\",\n    description: \"Set up BOGO offer on selected products\",\n    icon: \"Gift\",\n    category: \"sales\",\n    prompt: \"Set up a BOGO (buy one get one) offer. Recommend which products to include for highest profit retention.\",\n  },\n\n  // PRODUCTS\n  {\n    command: \"/import\",\n    label: \"Import Products\",\n    description: \"Import from AliExpress, Temu, Amazon, etc.\",\n    icon: \"Download\",\n    category: \"products\",\n    prompt: \"I want to import products. Tell me which platforms you can scrape from, then I'll paste a URL.\",\n    requiresInput: true,\n    inputLabel: \"Paste product URL or supplier store URL\",\n  },\n  {\n    command: \"/audit\",\n    label: \"Product Audit\",\n    description: \"Find products that need attention\",\n    icon: \"Search\",\n    category: \"products\",\n    prompt: \"Do a full audit of my products. Show me: 1) products with no images, 2) products with no description, 3) products with prices that look wrong, 4) products with low inventory. Then suggest fixes.\",\n  },\n  {\n    command: \"/rewrite\",\n    label: \"Rewrite Descriptions\",\n    description: \"Improve all product descriptions with AI\",\n    icon: \"Edit\",\n    category: \"products\",\n    prompt: \"Review all my products and identify which descriptions need improvement. For each, write a better version that will convert Nigerian buyers.\",\n  },\n  {\n    command: \"/price-check\",\n    label: \"Price Audit\",\n    description: \"Check if my prices are competitive\",\n    icon: \"TrendingUp\",\n    category: \"products\",\n    prompt: \"Audit my product prices. For each product, tell me if it's too high, too low, or just right based on the Nigerian market. Suggest specific price changes.\",\n  },\n\n  // MARKETING\n  {\n    command: \"/whatsapp\",\n    label: \"WhatsApp Broadcast\",\n    description: \"Send broadcast to customers\",\n    icon: \"MessageCircle\",\n    category: \"marketing\",\n    prompt: \"Help me write a WhatsApp broadcast. Suggest the best message type for my customer list right now (promo, restock alert, abandoned cart, win-back).\",\n    requiresInput: true,\n    inputLabel: \"What do you want to announce?\",\n  },\n  {\n    command: \"/email\",\n    label: \"Email Campaign\",\n    description: \"Create an email campaign\",\n    icon: \"Mail\",\n    category: \"marketing\",\n    prompt: \"Create an email campaign for my customers. Pick the best campaign type for right now and write the full email.\",\n    requiresInput: true,\n    inputLabel: \"Campaign goal (e.g. drive sales, announce new product)\",\n  },\n  {\n    command: \"/abandoned\",\n    label: \"Recover Abandoned Carts\",\n    description: \"Send recovery messages to abandoned carts\",\n    icon: \"ShoppingCart\",\n    category: \"marketing\",\n    prompt: \"Check my abandoned carts. Show me how many there are, total value at risk, and send a recovery WhatsApp/email to each.\",\n  },\n  {\n    command: \"/instagram\",\n    label: \"Instagram Post Copy\",\n    description: \"Write Instagram caption with hashtags\",\n    icon: \"Instagram\",\n    category: \"marketing\",\n    prompt: \"Write me an Instagram post caption with relevant Nigerian hashtags.\",\n    requiresInput: true,\n    inputLabel: \"What product/topic?\",\n  },\n  {\n    command: \"/tiktok\",\n    label: \"TikTok Script\",\n    description: \"Generate viral TikTok script\",\n    icon: \"Video\",\n    category: \"marketing\",\n    prompt: \"Write me a TikTok script that's likely to go viral in Nigeria. Hook in 3 seconds, fast cuts, call to action.\",\n    requiresInput: true,\n    inputLabel: \"What product?\",\n  },\n\n  // ANALYTICS\n  {\n    command: \"/insights\",\n    label: \"Store Insights\",\n    description: \"Daily AI summary of your store\",\n    icon: \"BarChart\",\n    category: \"analytics\",\n    prompt: \"Give me a complete insight report on my store right now: top performers, what needs attention, what's growing, what's dying, and 3 specific actions I should take today.\",\n  },\n  {\n    command: \"/trending\",\n    label: \"Trending Products\",\n    description: \"What's hot in Nigeria right now\",\n    icon: \"Flame\",\n    category: \"analytics\",\n    prompt: \"Show me what's trending in Nigeria right now. Categories with high demand, products selling fast on Jumia/Konga/TikTok Shop, seasonal opportunities.\",\n  },\n  {\n    command: \"/forecast\",\n    label: \"Sales Forecast\",\n    description: \"Predict next 30 days revenue\",\n    icon: \"LineChart\",\n    category: \"analytics\",\n    prompt: \"Forecast my sales for the next 30 days. Show predicted revenue, predicted orders, what's likely to drive growth, what could slow it down.\",\n  },\n\n  // OPERATIONS\n  {\n    command: \"/fulfill\",\n    label: \"Fulfill Orders\",\n    description: \"Process all pending orders\",\n    icon: \"Package\",\n    category: \"operations\",\n    prompt: \"Show me all unfulfilled orders. For each one, prepare the fulfillment with supplier details. I'll approve them and you process.\",\n  },\n  {\n    command: \"/refund\",\n    label: \"Process Refund\",\n    description: \"Handle a customer refund\",\n    icon: \"RotateCcw\",\n    category: \"operations\",\n    prompt: \"Help me process a refund. Ask me which order, then handle it end-to-end.\",\n    requiresInput: true,\n    inputLabel: \"Order ID or customer name\",\n  },\n  {\n    command: \"/stock\",\n    label: \"Stock Check\",\n    description: \"Inventory audit and reorder\",\n    icon: \"Archive\",\n    category: \"operations\",\n    prompt: \"Check my inventory levels. Show low stock items, items that need reorder, and items overstocked. Suggest restock actions.\",\n  },\n];\n\n// Get suggested commands based on store state\nexport async function getSuggestedCommands(storeId: string): Promise<QuickCommand[]> {\n  if (!storeId || storeId === \"public\") return QUICK_COMMANDS.slice(0, 6);\n\n  try {\n    const [products, orders, carts] = await Promise.all([\n      prisma.product.count({ where: { storeId } }).catch(() => 0),\n      prisma.order.count({ where: { storeId, fulfillmentStatus: \"UNFULFILLED\" } }).catch(() => 0),\n      (prisma as any).cart?.count?.({ where: { storeId, status: \"ABANDONED\" } }).catch(() => 0),\n    ]);\n\n    const suggested: QuickCommand[] = [];\n\n    // No products yet → suggest import\n    if (products === 0) {\n      suggested.push(QUICK_COMMANDS.find(c => c.command === \"/import\")!);\n      suggested.push(QUICK_COMMANDS.find(c => c.command === \"/trending\")!);\n    }\n\n    // Unfulfilled orders → suggest fulfill\n    if (orders > 0) {\n      suggested.push(QUICK_COMMANDS.find(c => c.command === \"/fulfill\")!);\n    }\n\n    // Abandoned carts → suggest recover\n    if (carts > 0) {\n      suggested.push(QUICK_COMMANDS.find(c => c.command === \"/abandoned\")!);\n    }\n\n    // Always suggest insights + flash sale\n    suggested.push(QUICK_COMMANDS.find(c => c.command === \"/insights\")!);\n    suggested.push(QUICK_COMMANDS.find(c => c.command === \"/flash-sale\")!);\n\n    return suggested.filter(Boolean).slice(0, 6);\n  } catch {\n    return QUICK_COMMANDS.slice(0, 6);\n  }\n}\n","backend/src/services/kai.opportunity.service.ts":"// ============================================================\n// KIRO Opportunity Engine\n// Proactively detects revenue opportunities, risks, and growth signals\n// Runs every 6 hours via cron, surfaces insights through pulse alerts\n// ============================================================\n\nimport { prisma } from \"../config/database\";\n\ninterface Opportunity {\n  type: \"price_increase\" | \"price_decrease\" | \"low_stock\" | \"high_demand\" | \"bundle\" | \"win_back\" | \"fraud_risk\" | \"seasonal\" | \"abandoned_value\" | \"viral_product\";\n  severity: \"high\" | \"medium\" | \"low\";\n  title: string;\n  message: string;\n  action?: string;\n  data?: any;\n  storeId: string;\n}\n\n// ─────────────────────────────────────────────────────────────\n// 1. PRICE OPTIMIZATION\n// Detect products that should change price based on velocity\n// ─────────────────────────────────────────────────────────────\nasync function detectPriceOpportunities(storeId: string): Promise<Opportunity[]> {\n  const opportunities: Opportunity[] = [];\n  const products = await prisma.product.findMany({\n    where: { storeId, status: \"ACTIVE\" as any },\n    take: 50,\n  }).catch(() => []);\n\n  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);\n\n  for (const product of products) {\n    // Count orders containing this product in last 30 days\n    const orderItems = await (prisma as any).orderItem?.count?.({\n      where: {\n        productId: product.id,\n        order: { createdAt: { gte: thirtyDaysAgo }, status: { not: \"CANCELLED\" } },\n      },\n    }).catch(() => 0) ?? 0;\n\n    // High demand → suggest price increase\n    if (orderItems >= 10 && (product as any).inventory > 5) {\n      opportunities.push({\n        type: \"high_demand\",\n        severity: \"high\",\n        title: `\"${product.name}\" is selling fast`,\n        message: `${orderItems} orders in 30 days. You could raise the price 10-15% and still sell out. Current: ₦${product.price.toLocaleString()}.`,\n        action: `Increase price of \"${product.name}\" by 12% from ₦${product.price.toLocaleString()} to ₦${Math.round(Number(product.price) * 1.12).toLocaleString()}`,\n        data: { productId: product.id, currentPrice: product.price, suggestedPrice: Math.round(Number(product.price) * 1.12) },\n        storeId,\n      });\n    }\n\n    // Low demand → suggest price decrease or flash sale\n    if (orderItems === 0 && (product as any).inventory > 10) {\n      const daysSinceCreated = (Date.now() - new Date(product.createdAt).getTime()) / (1000 * 60 * 60 * 24);\n      if (daysSinceCreated > 14) {\n        opportunities.push({\n          type: \"price_decrease\",\n          severity: \"medium\",\n          title: `\"${product.name}\" hasn't sold in 30 days`,\n          message: `Listed ${Math.round(daysSinceCreated)} days ago, zero orders. Try a 20% flash sale or rewrite the description to boost visibility.`,\n          action: `Create flash sale for \"${product.name}\" at 20% off`,\n          data: { productId: product.id, currentPrice: product.price, suggestedDiscount: 20 },\n          storeId,\n        });\n      }\n    }\n\n    // Low stock + high demand → reorder alert\n    if ((product as any).inventory <= 3 && orderItems >= 5) {\n      opportunities.push({\n        type: \"low_stock\",\n        severity: \"high\",\n        title: `\"${product.name}\" running out`,\n        message: `Only ${(product as any).inventory} left and ${orderItems} sold this month. Reorder now or you'll miss sales.`,\n        action: `Restock \"${product.name}\"`,\n        data: { productId: product.id, currentStock: (product as any).inventory, suggestedRestock: Math.ceil(orderItems * 1.5) },\n        storeId,\n      });\n    }\n  }\n\n  return opportunities;\n}\n\n// ─────────────────────────────────────────────────────────────\n// 2. BUNDLE DETECTION\n// Find products frequently bought together → suggest as bundle\n// ─────────────────────────────────────────────────────────────\nasync function detectBundles(storeId: string): Promise<Opportunity[]> {\n  const opportunities: Opportunity[] = [];\n  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);\n\n  // Get recent multi-item orders\n  const orders = await prisma.order.findMany({\n    where: { storeId, createdAt: { gte: thirtyDaysAgo } },\n    include: { items: { include: { product: true } } },\n    take: 100,\n  }).catch(() => []);\n\n  // Build pair frequency map\n  const pairs: Record<string, { count: number; products: any[] }> = {};\n  for (const order of orders) {\n    const items = (order as any).items || [];\n    if (items.length < 2) continue;\n    for (let i = 0; i < items.length; i++) {\n      for (let j = i + 1; j < items.length; j++) {\n        const key = [items[i].productId, items[j].productId].sort().join(\"|\");\n        if (!pairs[key]) pairs[key] = { count: 0, products: [items[i].product, items[j].product] };\n        pairs[key].count++;\n      }\n    }\n  }\n\n  // Pairs ordered together 3+ times = bundle opportunity\n  const topPairs = Object.entries(pairs).filter(([, v]) => v.count >= 3).sort((a, b) => b[1].count - a[1].count).slice(0, 3);\n\n  for (const [, pair] of topPairs) {\n    const [a, b] = pair.products;\n    if (!a || !b) continue;\n    const total = Number(a.price) + Number(b.price);\n    const bundlePrice = Math.round(total * 0.9); // 10% off\n    opportunities.push({\n      type: \"bundle\",\n      severity: \"medium\",\n      title: `Bundle opportunity: ${a.name} + ${b.name}`,\n      message: `${pair.count} customers bought these together. Create a bundle for ₦${bundlePrice.toLocaleString()} (saves them ₦${(total - bundlePrice).toLocaleString()}).`,\n      action: `Create bundle: ${a.name} + ${b.name}`,\n      data: { productIds: [a.id, b.id], suggestedPrice: bundlePrice, savings: total - bundlePrice },\n      storeId,\n    });\n  }\n\n  return opportunities;\n}\n\n// ─────────────────────────────────────────────────────────────\n// 3. ABANDONED CART VALUE\n// Total value waiting to be recovered\n// ─────────────────────────────────────────────────────────────\nasync function detectAbandonedValue(storeId: string): Promise<Opportunity[]> {\n  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);\n  const abandoned = await (prisma as any).cart?.findMany?.({\n    where: { storeId, status: \"ABANDONED\", updatedAt: { gte: sevenDaysAgo } },\n    include: { items: true },\n  }).catch(() => []) ?? [];\n\n  if (abandoned.length === 0) return [];\n\n  const totalValue = abandoned.reduce((sum: number, cart: any) =>\n    sum + (cart.items || []).reduce((s: number, i: any) => s + Number(i.price) * i.quantity, 0), 0);\n\n  if (totalValue < 5000) return [];\n\n  return [{\n    type: \"abandoned_value\",\n    severity: \"high\",\n    title: `₦${totalValue.toLocaleString()} sitting in abandoned carts`,\n    message: `${abandoned.length} customers added to cart but didn't checkout (last 7 days). A WhatsApp message could recover 15-20% of this.`,\n    action: `Send recovery messages to ${abandoned.length} abandoned carts`,\n    data: { count: abandoned.length, value: totalValue },\n    storeId,\n  }];\n}\n\n// ─────────────────────────────────────────────────────────────\n// 4. WIN-BACK OPPORTUNITY\n// Customers who haven't ordered in 45-90 days\n// ─────────────────────────────────────────────────────────────\nasync function detectWinBack(storeId: string): Promise<Opportunity[]> {\n  const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000);\n  const fortyFiveDaysAgo = new Date(Date.now() - 45 * 24 * 60 * 60 * 1000);\n\n  const customers = await (prisma as any).storeCustomer?.findMany?.({\n    where: {\n      storeId,\n      lastOrderAt: { gte: ninetyDaysAgo, lte: fortyFiveDaysAgo },\n      totalSpent: { gte: 5000 },\n    },\n    take: 100,\n  }).catch(() => []) ?? [];\n\n  if (customers.length < 3) return [];\n\n  const totalValue = customers.reduce((s: number, c: any) => s + Number(c.totalSpent || 0), 0);\n\n  return [{\n    type: \"win_back\",\n    severity: \"medium\",\n    title: `${customers.length} loyal customers gone quiet`,\n    message: `Bought from you 45-90 days ago, total lifetime value ₦${totalValue.toLocaleString()}. A 15% comeback offer would likely bring 20-30% of them back.`,\n    action: `Send win-back campaign to ${customers.length} customers`,\n    data: { count: customers.length, totalValue },\n    storeId,\n  }];\n}\n\n// ─────────────────────────────────────────────────────────────\n// 5. FRAUD / RISK DETECTOR\n// Flag suspicious order patterns\n// ─────────────────────────────────────────────────────────────\nasync function detectFraudRisks(storeId: string): Promise<Opportunity[]> {\n  const opportunities: Opportunity[] = [];\n  const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);\n\n  // Multiple orders from same email/phone in short time\n  const recentOrders = await prisma.order.findMany({\n    where: { storeId, createdAt: { gte: twentyFourHoursAgo } },\n    select: { id: true, customerEmail: true, customerPhone: true, total: true, status: true },\n  }).catch(() => []);\n\n  const emailCounts: Record<string, number> = {};\n  for (const order of recentOrders) {\n    const key = order.customerEmail || order.customerPhone || \"\";\n    if (!key) continue;\n    emailCounts[key] = (emailCounts[key] || 0) + 1;\n  }\n\n  const suspicious = Object.entries(emailCounts).filter(([, c]) => c >= 3);\n  if (suspicious.length > 0) {\n    opportunities.push({\n      type: \"fraud_risk\",\n      severity: \"high\",\n      title: `${suspicious.length} customer${suspicious.length > 1 ? \"s\" : \"\"} placing many orders`,\n      message: `Same email/phone made 3+ orders in 24 hours. Could be a wholesale buyer OR a fraud attempt. Review before fulfilling.`,\n      action: `Review high-volume customers`,\n      data: { customers: suspicious.map(([k, c]) => ({ identifier: k, count: c })) },\n      storeId,\n    });\n  }\n\n  return opportunities;\n}\n\n// ─────────────────────────────────────────────────────────────\n// 6. SEASONAL OPPORTUNITY (Nigeria-specific)\n// ─────────────────────────────────────────────────────────────\nfunction detectSeasonalOpportunities(storeId: string): Opportunity[] {\n  const now = new Date();\n  const month = now.getMonth() + 1;\n  const day = now.getDate();\n  const opportunities: Opportunity[] = [];\n\n  // Christmas push (Nov-Dec)\n  if (month === 11 || (month === 12 && day < 26)) {\n    opportunities.push({\n      type: \"seasonal\",\n      severity: \"high\",\n      title: \"Christmas shopping season is here\",\n      message: \"Nigerian customers are searching for gifts, ankara, jewelry, gadgets, kids toys. Push promotions, free gift wrapping, and Christmas-themed bundles now.\",\n      action: \"Launch Christmas campaign\",\n      storeId,\n    });\n  }\n\n  // Valentine's (early Feb)\n  if (month === 2 && day < 14) {\n    opportunities.push({\n      type: \"seasonal\",\n      severity: \"high\",\n      title: `${14 - day} days until Valentine's Day`,\n      message: \"Couples in Lagos and Abuja are searching for gifts, flowers, watches, perfumes. Launch a V-Day bundle now.\",\n      action: \"Create Valentine's bundle\",\n      storeId,\n    });\n  }\n\n  // Black Friday (late November)\n  if (month === 11 && day >= 20 && day <= 30) {\n    opportunities.push({\n      type: \"seasonal\",\n      severity: \"high\",\n      title: \"Black Friday is this week\",\n      message: \"Nigerian shoppers are primed to spend. Even 25% off on hero products can 3x your normal weekly revenue.\",\n      action: \"Set up Black Friday flash sale\",\n      storeId,\n    });\n  }\n\n  // End of month payday rush (28-30)\n  if (day >= 27 && day <= 30) {\n    opportunities.push({\n      type: \"seasonal\",\n      severity: \"medium\",\n      title: \"Payday week — Nigerian shoppers are buying\",\n      message: \"27th–30th is peak conversion in Nigeria. Push your best products now with WhatsApp broadcasts.\",\n      action: \"Send payday WhatsApp broadcast\",\n      storeId,\n    });\n  }\n\n  return opportunities;\n}\n\n// ─────────────────────────────────────────────────────────────\n// MAIN: Scan a store for all opportunities\n// ─────────────────────────────────────────────────────────────\nexport async function scanStoreOpportunities(storeId: string): Promise<Opportunity[]> {\n  const [prices, bundles, abandoned, winBack, fraud, seasonal] = await Promise.all([\n    detectPriceOpportunities(storeId).catch(() => []),\n    detectBundles(storeId).catch(() => []),\n    detectAbandonedValue(storeId).catch(() => []),\n    detectWinBack(storeId).catch(() => []),\n    detectFraudRisks(storeId).catch(() => []),\n    Promise.resolve(detectSeasonalOpportunities(storeId)),\n  ]);\n\n  return [...prices, ...bundles, ...abandoned, ...winBack, ...fraud, ...seasonal];\n}\n\n// ─────────────────────────────────────────────────────────────\n// Generate a daily AI brief\n// ─────────────────────────────────────────────────────────────\nexport async function generateDailyBrief(storeId: string): Promise<{\n  greeting: string;\n  highlights: string[];\n  topActions: string[];\n  warningCount: number;\n  opportunityCount: number;\n}> {\n  const opps = await scanStoreOpportunities(storeId);\n\n  // Recent metrics\n  const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);\n  const yesterdayOrders = await prisma.order.count({\n    where: { storeId, createdAt: { gte: twentyFourHoursAgo }, status: { not: \"CANCELLED\" as any } },\n  }).catch(() => 0);\n\n  const yesterdayRevenue = await prisma.order.aggregate({\n    where: { storeId, createdAt: { gte: twentyFourHoursAgo }, status: { not: \"CANCELLED\" as any } },\n    _sum: { total: true },\n  }).catch(() => ({ _sum: { total: 0 } }));\n\n  const revenue = Number((yesterdayRevenue as any)?._sum?.total || 0);\n\n  const hour = new Date().getHours();\n  const greeting = hour < 12 ? \"Good morning\" : hour < 17 ? \"Good afternoon\" : \"Good evening\";\n\n  const highlights: string[] = [];\n  if (yesterdayOrders > 0) {\n    highlights.push(`${yesterdayOrders} order${yesterdayOrders !== 1 ? \"s\" : \"\"} in the last 24 hours worth ₦${revenue.toLocaleString()}`);\n  } else {\n    highlights.push(\"No orders in the last 24 hours — let's change that today\");\n  }\n\n  const highOpps = opps.filter(o => o.severity === \"high\");\n  const mediumOpps = opps.filter(o => o.severity === \"medium\");\n  if (highOpps.length > 0) highlights.push(`${highOpps.length} high-priority opportunity${highOpps.length !== 1 ? \"ies\" : \"y\"} need your attention`);\n  if (mediumOpps.length > 0) highlights.push(`${mediumOpps.length} other thing${mediumOpps.length !== 1 ? \"s\" : \"\"} worth checking`);\n\n  const topActions = opps.slice(0, 3).map(o => o.action || o.title).filter(Boolean) as string[];\n\n  return {\n    greeting: `${greeting}!`,\n    highlights,\n    topActions,\n    warningCount: opps.filter(o => o.type === \"fraud_risk\" || o.type === \"low_stock\").length,\n    opportunityCount: opps.length,\n  };\n}\n","backend/src/routes/kai.routes.ts":"// ============================================================\n// KAI — Complete Routes (10/10)\n// Path: backend/src/routes/kai.routes.ts\n// ============================================================\nimport { Router } from \"express\";\nimport rateLimit from \"express-rate-limit\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  getMorningBrief, getGreeting, getConversations, getConversation, smartChat,\n  executeAction, updateConversation, deleteConversation,\n  deleteAllConversations, getKaiMemories, deleteKaiMemory,\n  getPulseAlerts, readPulseAlert, getSkills, createSkill,\n  deleteSkill, useSkill, analyzeVoice, getGoals, createGoal,\n} from \"../controllers/kai.controller\";\nimport {\n  fbAdsHandler,\n  tiktokSpyHandler,\n  saturationHandler,\n} from \"../controllers/kai.scraper.controller\";\nimport {\n  generateImageHandler,\n  scrapeUrlHandler as scrapeUrl,\n  scrapeBatchHandler as scrapeBatch,\n  researchTopicHandler as researchTopic,\n  trendingHandler as trending,\n  profitCalcHandler as profitCalc,\n} from \"../controllers/kai.scraper.controller\";\nimport { QUICK_COMMANDS, getSuggestedCommands } from \"../services/kai.commands.service\";\nimport { scanStoreOpportunities, generateDailyBrief } from \"../services/kai.opportunity.service\";\n\nconst router = Router();\n\nconst kaiLimit = rateLimit({\n  windowMs: 60 * 1000,\n  max: 25,\n  message: { success: false, message: \"Too many KAI requests — slow down a bit\" },\n});\n\n\n// GET /api/kai/health — test KIRO is ready (no auth needed)\nrouter.get(\"/health\", async (req: any, res: any) => {\n  const apiKey = process.env.ANTHROPIC_API_KEY;\n  const hasKey = !!(apiKey && apiKey.startsWith(\"sk-ant\"));\n  \n  let dbOk = false;\n  try {\n    const { PrismaClient } = require(\"@prisma/client\");\n    const p = new PrismaClient();\n    await p.$queryRaw`SELECT 1`;\n    await p.$disconnect();\n    dbOk = true;\n  } catch(e: any) {}\n\n  res.json({\n    ok: hasKey && dbOk,\n    apiKey: hasKey ? \"configured\" : \"MISSING - add ANTHROPIC_API_KEY to Render env\",\n    db: dbOk ? \"connected\" : \"error\",\n    model: process.env.KIRO_MODEL || \"claude-haiku-4-5-20251001\",\n  });\n});\n\nrouter.use(authenticate);\n\n// Core chat\nrouter.get   (\"/greeting\",              getGreeting);\nrouter.post  (\"/smart-chat\",            kaiLimit, smartChat);\nrouter.post  (\"/action\",                executeAction);\n\n// Conversations\nrouter.get   (\"/conversations\",         getConversations);\nrouter.get   (\"/conversation/:id\",      getConversation);\nrouter.patch (\"/conversation/:id\",      updateConversation);\nrouter.delete(\"/conversation/:id\",      deleteConversation);\nrouter.delete(\"/conversations/all\",     deleteAllConversations);\n\n// Memory\nrouter.get   (\"/memories\",              getKaiMemories);\nrouter.delete(\"/memory/:key\",           deleteKaiMemory);\n\n// KAI Pulse (proactive alerts)\nrouter.get   (\"/pulse\",                 getPulseAlerts);\nrouter.patch (\"/pulse/:id/read\",        readPulseAlert);\n\n// Skills (saved prompts)\n// Quick Commands — power user shortcuts\nrouter.get(\"/commands\", (req, res) => {\n  res.json({ success: true, data: QUICK_COMMANDS });\n});\nrouter.get(\"/commands/suggested\", async (req, res) => {\n  const storeId = (req.query.storeId as string) || \"\";\n  const data = await getSuggestedCommands(storeId);\n  res.json({ success: true, data });\n});\n\n// Opportunity Engine — proactive store intelligence\nrouter.get(\"/opportunities\", async (req, res) => {\n  try {\n    const storeId = (req.query.storeId as string) || \"\";\n    if (!storeId) return res.json({ success: true, data: [] });\n    const data = await scanStoreOpportunities(storeId);\n    res.json({ success: true, data });\n  } catch (e: any) {\n    res.json({ success: true, data: [] });\n  }\n});\n\nrouter.get(\"/daily-brief\", async (req, res) => {\n  try {\n    const storeId = (req.query.storeId as string) || \"\";\n    if (!storeId) return res.json({ success: true, data: null });\n    const data = await generateDailyBrief(storeId);\n    res.json({ success: true, data });\n  } catch (e: any) {\n    res.json({ success: true, data: null });\n  }\n});\n\nrouter.get   (\"/skills\",                getSkills);\nrouter.post  (\"/skills\",                createSkill);\nrouter.delete(\"/skills/:id\",            deleteSkill);\nrouter.post  (\"/skills/:id/use\",        useSkill);\n\n// Brand voice\nrouter.post  (\"/analyze-voice\",         analyzeVoice);\n\n// Goals\nrouter.get   (\"/goals\",                 getGoals as any);\nrouter.post  (\"/goals\",                 createGoal as any);\n\n// GET /api/kai/test-key — check API key config (no auth required for diagnosis)\n// Web scraper & research\nrouter.post  (\"/generate-image\",         generateImageHandler);\nrouter.post  (\"/scrape-url\",            scrapeUrl);\nrouter.post  (\"/fb-ads\",               fbAdsHandler);\nrouter.post  (\"/tiktok-spy\",           tiktokSpyHandler);\nrouter.post  (\"/saturation\",           saturationHandler);\nrouter.post  (\"/scrape-batch\",          scrapeBatch);\nrouter.post  (\"/research-market\",       researchTopic);\nrouter.get   (\"/trending\",              trending);\nrouter.post  (\"/profit-calc\",           profitCalc);\n\nrouter.get(\"/test-key\", ((req: any, res: any) => {\n  const key = process.env.ANTHROPIC_API_KEY;\n  const model = process.env.KIRO_MODEL || \"claude-sonnet-4-5\";\n  if (!key) { res.status(500).json({ success: false, message: \"ANTHROPIC_API_KEY not set\" }); return; }\n  res.json({ success: true, keyPrefix: key.slice(0,10)+\"...\", model, length: key.length });\n}) as any);\n\nexport default router;\n","frontend/src/components/kai/KIROChat.tsx":"\"use client\";\n/**\n * KIROChat — DropOS Commerce AI\n * Fresh build. No legacy. Clean design system.\n *\n * DESIGN: \"Warm Precision\"\n * Light default: Linen #F7F6F3 → Ink #111827, Violet #7C3AED accent\n * Dark:          Obsidian #0D0D14 → Snow #F9F8FF, same accent\n * Font: Geist (display) + Inter (body) — loaded from CDN\n *\n * LAYOUT: Column flex, height:100%, minHeight:0 everywhere.\n * No absolute positioning in the main flow.\n * KIRO_ACTION: buffered server-side, stripped client-side.\n */\n\nimport React, { useState, useRef, useEffect, useCallback } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { api, uploadAPI } from \"../../lib/api\";\nimport toast from \"react-hot-toast\";\n\n// ── constants ──────────────────────────────────────────────────────────────────\nconst BASE   = process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\";\nconst ACCENT = \"#7C3AED\";\nconst ACCENT_D = \"#5B21B6\";\n\n\n// ── Suggestion card icon — monochrome SVG ─────────────────────\nconst SUGGESTION_ICONS: Record<string,string> = {\n  pulse:  \"M3 12h4l3-9 4 18 3-9h4\",\n  trend:  \"M22 7l-9.5 9.5-5-5L1 17\",\n  import: \"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3\",\n  flash:  \"M13 2L3 14h9l-1 8 10-12h-9z\",\n  ad:     \"M12 20h9M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z\",\n  growth: \"M18 20V10M12 20V4M6 20v-6\",\n  default:\"M12 5v14M5 12h14\",\n};\nfunction SuggestionIcon({ id, color }: { id: string; color: string }) {\n  const d = SUGGESTION_ICONS[id] || SUGGESTION_ICONS.default;\n  const isFill = id === \"flash\";\n  return (\n    <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill={isFill ? color : \"none\"}\n      stroke={isFill ? \"none\" : color} strokeWidth=\"1.75\" strokeLinecap=\"round\" strokeLinejoin=\"round\"\n      style={{ display:\"block\", marginBottom:6, opacity:0.65 }}>\n      <path d={d}/>\n    </svg>\n  );\n}\n\n// ── types ──────────────────────────────────────────────────────────────────────\ntype Mode = \"light\" | \"dark\";\ninterface Msg {\n  id:         string;\n  role:       \"user\" | \"assistant\";\n  content:    string;\n  streaming?: boolean;\n  imageUrl?:  string;\n  actions?:   Action[];\n  ts?:        string;\n  thumbs?:    \"up\" | \"down\";\n}\ninterface Action {\n  type:     string;\n  payload:  Record<string,unknown>;\n  approved?: boolean;\n}\n\n// ── theme tokens ───────────────────────────────────────────────────────────────\nconst T = {\n  light: {\n    bg:       \"#F7F6F3\",\n    surface:  \"#FFFFFF\",\n    elevated: \"#F0EFE9\",\n    border:   \"rgba(0,0,0,0.08)\",\n    borderFocus: ACCENT + \"60\",\n    text:     \"#111827\",\n    sub:      \"#6B7280\",\n    muted:    \"#9CA3AF\",\n    accent:   ACCENT,\n    accentD:  ACCENT_D,\n    accentBg: ACCENT + \"12\",\n    userBg:   `linear-gradient(145deg, ${ACCENT}, ${ACCENT_D})`,\n    userText: \"#ffffff\",\n    shadow:   \"0 1px 4px rgba(0,0,0,0.06), 0 4px 20px rgba(0,0,0,0.04)\",\n    shadowMd: \"0 4px 24px rgba(0,0,0,0.10)\",\n    green:    \"#059669\",\n    amber:    \"#D97706\",\n    red:      \"#DC2626\",\n    scrollbar: \"rgba(0,0,0,0.12)\",\n  },\n  dark: {\n    bg:       \"#0D0D14\",\n    surface:  \"#13131F\",\n    elevated: \"#1A1A2A\",\n    border:   \"rgba(255,255,255,0.07)\",\n    borderFocus: ACCENT + \"70\",\n    text:     \"#F9F8FF\",\n    sub:      \"#A0A0C0\",\n    muted:    \"#606080\",\n    accent:   \"#9061F9\",\n    accentD:  ACCENT,\n    accentBg: ACCENT + \"18\",\n    userBg:   `linear-gradient(145deg, ${ACCENT}, ${ACCENT_D})`,\n    userText: \"#ffffff\",\n    shadow:   \"0 1px 4px rgba(0,0,0,0.4)\",\n    shadowMd: \"0 4px 24px rgba(0,0,0,0.5)\",\n    green:    \"#10B981\",\n    amber:    \"#F59E0B\",\n    red:      \"#F87171\",\n    scrollbar: \"rgba(255,255,255,0.1)\",\n  },\n};\n\n// ── clean KIRO_ACTION from text ────────────────────────────────────────────────\nfunction cleanText(raw: string): string {\n  if (!raw) return \"\";\n  let result = \"\";\n  let i = 0;\n  while (i < raw.length) {\n    const markerIdx = raw.indexOf(\"KIRO_ACTION\", i);\n    if (markerIdx === -1) { result += raw.slice(i); break; }\n    result += raw.slice(i, markerIdx);\n    let j = markerIdx + 11;\n    while (j < raw.length && /[\\s:`]/.test(raw[j])) j++;\n    if (j < raw.length && raw[j] === \"{\") {\n      let depth = 0;\n      while (j < raw.length) {\n        if (raw[j] === \"{\") depth++;\n        else if (raw[j] === \"}\") { depth--; if (depth === 0) { j++; break; } }\n        j++;\n      }\n      while (j < raw.length && (raw[j] === \"\\n\" || raw[j] === \"`\" || raw[j] === \" \")) j++;\n    }\n    i = j;\n  }\n  return result\n    .replace(/```json[\\s\\S]*?```/gi, \"\")\n    .replace(/```[\\s\\S]*?```/g, \"\")\n    .replace(/\\*\\*([^*]+)\\*\\*/g, \"$1\")\n    .replace(/\\*([^*\\n]+)\\*/g, \"$1\")\n    .replace(/^#{1,6}\\s/gm, \"\")\n    .replace(/━+/g, \"\").replace(/^[-=]{3,}\\s*$/gm, \"\")\n    .replace(/\\n{3,}/g, \"\\n\\n\").trim();\n}\n\n// ── parse actions from text ────────────────────────────────────────────────────\nfunction parseActions(text: string): Action[] {\n  const actions: Action[] = [];\n  const re = /KIRO_ACTION\\s*:?\\s*/g;\n  let match: RegExpExecArray | null;\n  while ((match = re.exec(text)) !== null) {\n    const start = text.indexOf(\"{\", match.index + match[0].length);\n    if (start === -1) continue;\n    let depth = 0, j = start;\n    while (j < text.length) {\n      if (text[j] === \"{\") depth++;\n      else if (text[j] === \"}\") { depth--; if (depth === 0) { j++; break; } }\n      j++;\n    }\n    try {\n      const obj = JSON.parse(text.slice(start, j));\n      if (obj.type) actions.push({ type: obj.type, payload: obj.payload || obj });\n    } catch {}\n  }\n  return actions;\n}\n\n// ── action card labels ─────────────────────────────────────────────────────────\nconst ACTION_META: Record<string, { icon: string; label: string; cta: string }> = {\n  add_product:           { icon:\"\", label:\"Add product\",         cta:\"Add to store\"    },\n  import_from_url:       { icon:\"\", label:\"Import product\",      cta:\"Import\"          },\n  update_price:          { icon:\"\", label:\"Update price\",        cta:\"Update\"          },\n  update_stock:          { icon:\"\", label:\"Update stock\",        cta:\"Update\"          },\n  create_coupon:         { icon:\"\", label:\"Create coupon\",       cta:\"Create\"          },\n  create_coupon_v2:      { icon:\"\", label:\"Create coupon\",       cta:\"Create\"          },\n  fulfill_order:         { icon:\"\", label:\"Fulfill order\",       cta:\"Fulfill\"         },\n  update_order_status:   { icon:\"\", label:\"Update order\",        cta:\"Update\"          },\n  create_flash_sale:     { icon:\"\", label:\"Flash sale\",          cta:\"Launch\"          },\n  archive_product:       { icon:\"\", label:\"Archive product\",     cta:\"Archive\"         },\n  delete_product:        { icon:\"\", label:\"Delete product\",      cta:\"Delete\"          },\n  duplicate_product:     { icon:\"\", label:\"Duplicate product\",   cta:\"Duplicate\"       },\n  add_tracking:          { icon:\"\", label:\"Add tracking\",        cta:\"Add\"             },\n  process_refund:        { icon:\"\", label:\"Process refund\",      cta:\"Refund\"          },\n  send_email:            { icon:\"\", label:\"Send email\",          cta:\"Send\"            },\n  send_whatsapp:         { icon:\"\", label:\"Send WhatsApp\",       cta:\"Send\"            },\n  bulk_update_prices:    { icon:\"\", label:\"Bulk price update\",   cta:\"Update all\"      },\n  update_store_description:{ icon:\"\", label:\"Update store\",     cta:\"Update\"          },\n  update_product:        { icon:\"\", label:\"Update product\",      cta:\"Save\"            },\n};\n\n// ── Time greeting ──────────────────────────────────────────────────────────────\nfunction getGreeting(name: string) {\n  const h = new Date().getHours();\n  const firstName = name.split(\" \")[0];\n  if (h < 5)  return `Still up, ${firstName}?`;\n  if (h < 12) return `Good morning, ${firstName}.`;\n  if (h < 17) return `Good afternoon, ${firstName}.`;\n  if (h < 21) return `Good evening, ${firstName}.`;\n  return `Late night, ${firstName}.`;\n}\n\n// ── KIRO Logo ──────────────────────────────────────────────────────────────────\nfunction KIROLogo({ size = 28 }: { size?: number }) {\n  return (\n    <div style={{\n      width: size, height: size, borderRadius: Math.round(size * 0.27),\n      background: `linear-gradient(145deg, ${ACCENT}, ${ACCENT_D})`,\n      display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0,\n      boxShadow: `0 2px 8px ${ACCENT}40`,\n    }}>\n      <svg width={size * 0.44} height={size * 0.44} viewBox=\"0 0 24 24\" fill=\"none\">\n        <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\" fillOpacity={0.95}/>\n      </svg>\n    </div>\n  );\n}\n\n// ── Spinner ────────────────────────────────────────────────────────────────────\nfunction Spinner({ size = 16, color = ACCENT }: { size?: number; color?: string }) {\n  return <div style={{ width: size, height: size, borderRadius: \"50%\", border: `2px solid ${color}30`, borderTopColor: color, animation: \"ks 0.7s linear infinite\", flexShrink: 0 }}/>;\n}\n\n// ── Action card ────────────────────────────────────────────────────────────────\nfunction ActionCard({ action, onApprove, onDismiss, t }: { action: Action; onApprove:(a:Action)=>void; onDismiss:(a:Action)=>void; t: typeof T.light }) {\n  const [loading, setLoading] = useState(false);\n  const [done,    setDone]    = useState(false);\n  const meta = ACTION_META[action.type] || { icon:\"\", label: action.type.replace(/_/g,\" \"), cta:\"Run\" };\n  if (done) return null;\n\n  const p = action.payload as any;\n  const summary = p?.name || p?.url?.slice(0,35) || p?.code || p?.trackingNumber || p?.message?.slice(0,40) || p?.status || \"\";\n\n  return (\n    <motion.div initial={{ opacity:0, y:4 }} animate={{ opacity:1, y:0 }}\n      style={{ marginTop: 10, borderRadius: 12, border: `1px solid ${t.border}`, background: t.surface, overflow: \"hidden\" }}>\n      <div style={{ padding: \"10px 14px 8px\", display: \"flex\", alignItems: \"flex-start\", gap: 8 }}>\n        <span style={{ fontSize: 18, flexShrink: 0, lineHeight: 1 }}>{meta.icon}</span>\n        <div style={{ flex: 1, minWidth: 0 }}>\n          <p style={{ fontSize: 12, fontWeight: 600, color: t.text, margin: 0 }}>{meta.label}</p>\n          {summary && <p style={{ fontSize: 11, color: t.sub, margin: \"2px 0 0\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{summary}</p>}\n        </div>\n      </div>\n      <div style={{ padding: \"0 14px 12px\", display: \"flex\", gap: 8 }}>\n        <button\n          onClick={async () => { setLoading(true); await onApprove(action); setDone(true); setLoading(false); }}\n          disabled={loading}\n          style={{ padding: \"6px 16px\", borderRadius: 8, border: \"none\", background: t.accent, color: \"#fff\", fontSize: 12, fontWeight: 600, cursor: \"pointer\", display: \"flex\", alignItems: \"center\", gap: 5 }}>\n          {loading ? <Spinner size={12} color=\"#fff\"/> : meta.cta}\n        </button>\n        <button onClick={() => { onDismiss(action); setDone(true); }}\n          style={{ padding: \"6px 12px\", borderRadius: 8, border: `1px solid ${t.border}`, background: \"transparent\", color: t.sub, fontSize: 12, cursor: \"pointer\" }}>\n          Dismiss\n        </button>\n      </div>\n    </motion.div>\n  );\n}\n\n// ── Message bubble ─────────────────────────────────────────────────────────────\nfunction MsgBubble({ msg, onApprove, onDismiss, onRate, onRegen, onPin, isPinned, onEdit, t }: {\n  msg: Msg; onApprove:(a:Action)=>void; onDismiss:(a:Action)=>void;\n  onRate:(id:string,v:\"up\"|\"down\")=>void; onRegen:(id:string)=>void;\n  onPin:(id:string)=>void; isPinned:boolean; onEdit:(id:string,txt:string)=>void;\n  t: typeof T.light;\n}) {\n  const [show, setShow] = useState(false);\n  const isUser = msg.role === \"user\";\n  const text   = cleanText(msg.content || \"\");\n\n  return (\n    <motion.div\n      initial={{ opacity: 0, y: 6 }}\n      animate={{ opacity: 1, y: 0 }}\n      transition={{ duration: 0.2 }}\n      onMouseEnter={() => setShow(true)}\n      onMouseLeave={() => setShow(false)}\n      style={{ display: \"flex\", flexDirection: isUser ? \"row-reverse\" : \"row\", gap: 8, alignItems: \"flex-end\", marginBottom: 20, position: \"relative\" }}>\n\n      {!isUser && <KIROLogo size={26}/>}\n\n      <div style={{ maxWidth: \"80%\", minWidth: 0 }}>\n        {/* Image */}\n        {msg.imageUrl && (\n          <img src={msg.imageUrl} alt=\"\" style={{ maxWidth: \"100%\", maxHeight: 200, borderRadius: 10, marginBottom: 6, display: \"block\", objectFit: \"cover\" }} onError={e=>(e.currentTarget.style.display=\"none\")}/>\n        )}\n\n        {/* Text bubble */}\n        <div style={{\n          padding: isUser ? \"10px 15px\" : \"0\",\n          borderRadius: isUser ? \"18px 18px 4px 18px\" : \"0\",\n          background: isUser ? t.userBg : \"transparent\",\n          color: isUser ? t.userText : t.text,\n          fontSize: 14, lineHeight: 1.7,\n          boxShadow: isUser ? `0 2px 10px ${ACCENT}30` : \"none\",\n        }}>\n          {msg.streaming && !msg.content ? (\n            <div style={{ display:\"flex\", gap:4, alignItems:\"center\", padding:\"3px 0\" }}>\n              {[0,1,2].map(i=>(\n                <motion.div key={i} style={{ width:5, height:5, borderRadius:\"50%\", background: t.muted }}\n                  animate={{ y:[0,-4,0], opacity:[0.4,1,0.4] }}\n                  transition={{ duration:0.6, repeat:Infinity, delay:i*0.13 }}/>\n              ))}\n              <span style={{ fontSize:12, color: t.muted, marginLeft:6 }}>KIRO is thinking</span>\n            </div>\n          ) : (\n            <span style={{ whiteSpace: \"pre-wrap\", wordBreak: \"break-word\" }}>\n              {text}\n              {msg.streaming && <motion.span animate={{ opacity:[1,0] }} transition={{ duration:0.5, repeat:Infinity }} style={{ display:\"inline-block\", marginLeft:1 }}>▋</motion.span>}\n            </span>\n          )}\n\n          {/* Action cards */}\n          {!isUser && msg.actions?.map((a,i) => (\n            <ActionCard key={i} action={a} onApprove={onApprove} onDismiss={onDismiss} t={t}/>\n          ))}\n        </div>\n\n        {/* Toolbar */}\n        <AnimatePresence>\n          {show && !msg.streaming && (\n            <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}\n              style={{ display:\"flex\", gap:3, marginTop:5, padding:\"0 2px\" }}>\n              {[\"📋\",\"👍\",\"👎\",\"↻\",\"🔊\"].map((icon, i) => (\n                <button key={i} title={[\"Copy\",\"Helpful\",\"Not helpful\",\"Retry\",\"Listen\"][i]}\n                  onClick={() => {\n                    if (i===0) navigator.clipboard.writeText(text);\n                    if (i===1) onRate(msg.id,\"up\");\n                    if (i===2) onRate(msg.id,\"down\");\n                    if (i===3) onRegen(msg.id);\n                    if (i===4) { const u = new SpeechSynthesisUtterance(text.slice(0,500)); u.lang=\"en-NG\"; window.speechSynthesis.speak(u); }\n                  }}\n                  style={{ width:24, height:24, borderRadius:6, border:`1px solid ${t.border}`, background: t.surface, color: t.sub, cursor:\"pointer\", fontSize:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  {icon}\n                </button>\n              ))}\n              {/* Pin */}\n              <button title={isPinned?\"Unpin\":\"Pin message\"} onClick={()=>onPin(msg.id)}\n                style={{ width:24, height:24, borderRadius:6, border:`1px solid ${isPinned?t.accent:t.border}`, background:isPinned?`${t.accent}18`:t.surface, color:isPinned?t.accent:t.sub, cursor:\"pointer\", fontSize:11, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                📌\n              </button>\n              {/* Edit (user messages only) */}\n              {isUser && (\n                <button title=\"Edit message\" onClick={()=>onEdit(msg.id,text)}\n                  style={{ width:24, height:24, borderRadius:6, border:`1px solid ${t.border}`, background:t.surface, color:t.sub, cursor:\"pointer\", fontSize:11, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  ✏️\n                </button>\n              )}\n              {!isUser && (\n                <button title=\"Share to WhatsApp\"\n                  onClick={() => window.open(`https://wa.me/?text=${encodeURIComponent(text.slice(0,500))}`, \"_blank\")}\n                  style={{ width:24, height:24, borderRadius:6, border:`1px solid ${t.border}`, background: t.surface, color:\"#25D366\", cursor:\"pointer\", fontSize:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  📤\n                </button>\n              )}\n            </motion.div>\n          )}\n        </AnimatePresence>\n\n        {/* Timestamp */}\n        {msg.ts && !msg.streaming && (\n          <p style={{ fontSize:10, color: t.muted, margin:\"3px 0 0\", textAlign: isUser?\"right\":\"left\" }}>\n            {new Date(msg.ts).toLocaleTimeString([],{hour:\"2-digit\",minute:\"2-digit\"})}\n            {msg.thumbs && (msg.thumbs===\"up\"?\" · 👍\":\" · 👎\")}\n          </p>\n        )}\n      </div>\n    </motion.div>\n  );\n}\n\n// ── Welcome screen ─────────────────────────────────────────────────────────────\nfunction Welcome({ name, storeData, onSend, t }: { name:string; storeData:any; onSend:(m:string)=>void; t: typeof T.light }) {\n  const greeting = getGreeting(name || \"there\");\n  const sym      = storeData?.currencySymbol || \"₦\";\n\n  const QUICK = [\n    { svg:\"M3 3h18v2H3zm0 4h12v2H3zm0 4h18v2H3zm0 4h12v2H3z\", title:\"Store pulse\",       sub:\"Revenue · Health · What needs action\",  prompt:\"Give me my full store summary — revenue, orders, health score, and what I should focus on today.\" },\n    { svg:\"M2 20h20M6 20V10l6-6 6 6v10M9 20v-5h6v5\", title:\"Trending products\", sub:\"Live market research\",                   prompt:\"What products are trending right now in my market this week?\" },\n    { svg:\"M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-9-4v4l3 3\", title:\"Import product\",    sub:\"Any URL — AliExpress, Temu, Amazon\",     prompt:\"I want to import a product. Paste a link and I'll handle everything.\" },\n    { svg:\"M13 2L3 14h9l-1 8 10-12h-9z\", title:\"Flash sale\",        sub:\"Drive sales right now\",                  prompt:\"Help me set up a flash sale on my best products today.\" },\n    { svg:\"M12 20h9M16.5 3.5a2.121 2.121 0 013 3L7 19l-4 1 1-4L16.5 3.5z\", title:\"Write ad copy\",     sub:\"TikTok · WhatsApp · Instagram\",          prompt:\"Write high-converting ad copy for my top product across TikTok, WhatsApp, and Instagram.\" },\n    { svg:\"M22 12h-4l-3 9L9 3l-3 9H2\", title:\"Growth plan\",       sub:\"Specific 5-step plan\",                   prompt:\"Give me a specific 5-step plan to grow my store revenue this month based on my current data.\" },\n  ];\n\n  return (\n    <div style={{ flex:1, display:\"flex\", flexDirection:\"column\", alignItems:\"center\", justifyContent:\"center\", padding:\"28px 20px 20px\", overflowY:\"auto\", minHeight:0 }}>\n\n      {/* Orb */}\n      <motion.div initial={{ opacity:0, scale:0.7 }} animate={{ opacity:1, scale:1 }}\n        transition={{ type:\"spring\", stiffness:200, damping:18 }}\n        style={{ marginBottom:22, position:\"relative\" }}>\n        <motion.div animate={{ scale:[1,1.08,1] }} transition={{ duration:3, repeat:Infinity, ease:\"easeInOut\" }}>\n          <KIROLogo size={64}/>\n        </motion.div>\n        <motion.div animate={{ rotate:360 }} transition={{ duration:7, repeat:Infinity, ease:\"linear\" }}\n          style={{ position:\"absolute\", inset:-8, borderRadius:\"50%\", border:`1px dashed ${ACCENT}30` }}>\n          <div style={{ position:\"absolute\", top:-3, left:\"50%\", width:7, height:7, borderRadius:\"50%\", background: ACCENT, boxShadow:`0 0 6px ${ACCENT}`, transform:\"translateX(-50%)\" }}/>\n        </motion.div>\n      </motion.div>\n\n      {/* Greeting */}\n      <motion.div initial={{ opacity:0, y:10 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.1 }}\n        style={{ textAlign:\"center\", marginBottom:24 }}>\n        <h2 style={{ fontSize:22, fontWeight:700, color: t.text, margin:\"0 0 5px\", letterSpacing:\"-0.4px\" }}>\n          {greeting}\n        </h2>\n        <p style={{ fontSize:13, color: t.sub, margin:0 }}>Your commerce AI is ready.</p>\n      </motion.div>\n\n      {/* Store metrics */}\n      {storeData && (\n        <motion.div initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.15 }}\n          style={{ display:\"flex\", gap:8, flexWrap:\"wrap\", justifyContent:\"center\", marginBottom:24 }}>\n          {[\n            { label:\"Today\", value: storeData.revenueToday > 0 ? `${sym}${storeData.revenueToday.toLocaleString()}` : `${sym}0`, alert: false },\n            { label:\"Pending\", value: String(storeData.pendingOrders||0), alert: storeData.pendingOrders > 0 },\n            { label:\"Health\",  value: storeData.healthScore ? `${storeData.healthScore}/100` : \"–\", alert: false },\n          ].map(m => (\n            <div key={m.label} style={{ padding:\"7px 14px\", borderRadius:9, background: t.surface, border:`1px solid ${m.alert ? t.amber+\"40\" : t.border}`, boxShadow: m.alert ? `0 0 10px ${t.amber}18` : \"none\" }}>\n              <p style={{ fontSize:13, fontWeight:700, color: m.alert ? t.amber : t.accent, margin:0 }}>{m.value}</p>\n              <p style={{ fontSize:9, color: t.muted, margin:0, textTransform:\"uppercase\", letterSpacing:\"0.08em\", fontWeight:600 }}>{m.label}</p>\n            </div>\n          ))}\n        </motion.div>\n      )}\n\n      {/* Quick actions */}\n      <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} transition={{ delay:0.2 }}\n        style={{ width:\"100%\", maxWidth:480 }}>\n        <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:8, marginBottom:12 }}>\n          {QUICK.map((q,i) => (\n            <motion.button key={q.title}\n              initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.22+i*0.05 }}\n              whileHover={{ y:-2, transition:{ duration:0.12 } }} whileTap={{ scale:0.97 }}\n              onClick={() => onSend(q.prompt)}\n              style={{ padding:\"11px 10px\", borderRadius:11, border:`1px solid ${t.border}`, background: t.surface, cursor:\"pointer\", textAlign:\"left\", boxShadow: t.shadow }}>\n              <SuggestionIcon id={q.icon} color={t.sub}/>\n              <span style={{ fontSize:11, fontWeight:600, color: t.text, display:\"block\", lineHeight:1.3 }}>{q.title}</span>\n              <span style={{ fontSize:10, color: t.sub, display:\"block\", lineHeight:1.4, marginTop:1 }}>{q.sub}</span>\n            </motion.button>\n          ))}\n        </div>\n      </motion.div>\n\n      {/* Pending orders urgent card */}\n      {storeData?.pendingOrders > 0 && (\n        <motion.button initial={{ opacity:0 }} animate={{ opacity:1 }} transition={{ delay:0.6 }}\n          whileHover={{ y:-1 }} whileTap={{ scale:0.98 }}\n          onClick={() => onSend(`Help me fulfill my ${storeData.pendingOrders} pending orders right now.`)}\n          style={{ width:\"100%\", maxWidth:480, padding:\"10px 14px\", borderRadius:10, border:`1px solid ${t.amber}35`, background:`${t.amber}0A`, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", gap:10 }}>\n          <span style={{ fontSize:18 }}>📬</span>\n          <div style={{ flex:1, textAlign:\"left\" }}>\n            <p style={{ fontSize:13, fontWeight:600, color: t.amber, margin:0 }}>{storeData.pendingOrders} unfulfilled order{storeData.pendingOrders>1?\"s\":\"\"}</p>\n            <p style={{ fontSize:11, color:`${t.amber}90`, margin:0 }}>Customers are waiting — tap to act now</p>\n          </div>\n          <span style={{ color: t.amber, opacity:0.6 }}>→</span>\n        </motion.button>\n      )}\n\n      <p style={{ fontSize:11, color: t.muted, margin:\"14px 0 0\", textAlign:\"center\" }}>\n        Paste any product URL · Upload image or PDF · ⌘K\n      </p>\n    </div>\n  );\n}\n\n// ── Props ──────────────────────────────────────────────────────────────────────\ninterface KIROChatProps {\n  storeId?:               string;\n  conversationId?:        string;\n  briefMessage?:          string;\n  className?:             string;\n  onConversationCreated?: (id: string) => void;\n  onFirstMessage?:        (text: string) => void;\n}\n\n// ── Main component ─────────────────────────────────────────────────────────────\nexport default function KIROChat({ storeId: propStoreId, conversationId: initConvId, onConversationCreated, onFirstMessage }: KIROChatProps) {\n  const user    = useAuthStore(s => s.user);\n  const token   = useAuthStore(s => s.accessToken);\n  const storeId = propStoreId || user?.stores?.[0]?.id || \"\";\n\n  // ── state ──────────────────────────────────────────────────────────────────\n  const [mode,      setMode]      = useState<Mode>(\"light\");\n  const [messages,  setMessages]  = useState<Msg[]>([]);\n  const [input,     setInput]     = useState(\"\");\n  const [loading,   setLoading]   = useState(false);\n  const [convId,    setConvId]    = useState(initConvId || \"\");\n  const [storeData, setStoreData] = useState<any>(null);\n  const [attach,    setAttach]    = useState<any>(null);\n  const [uploading, setUploading] = useState(false);\n  const [listening, setListening] = useState(false);\n  const [voiceInterim, setVoiceInterim] = useState(\"\");\n  const [rateLimit,    setRateLimit]    = useState(false);\n  const [showSearch,   setShowSearch]   = useState(false);\n  const [searchQuery,  setSearchQuery]  = useState(\"\");\n  const [pinnedMsgs,   setPinnedMsgs]   = useState<string[]>([]);\n  const [showPinned,   setShowPinned]   = useState(false);\n  const [showScrollBtn,setShowScrollBtn]= useState(false);\n  const [editingId,    setEditingId]    = useState<string|null>(null);\n  const [editText,     setEditText]     = useState(\"\");\n  const [slashMenu,    setSlashMenu]    = useState(false);\n  const [suggestions,  setSuggestions]  = useState<string[]>([]);\n\n  const bottomRef = useRef<HTMLDivElement>(null);\n  const inputRef  = useRef<HTMLTextAreaElement>(null);\n  const abortRef  = useRef<AbortController | null>(null);\n  const fileRef   = useRef<HTMLInputElement>(null);\n  const recogRef   = useRef<any>(null);\n  const msgListRef  = useRef<HTMLDivElement>(null);\n  const searchRef   = useRef<HTMLInputElement>(null);\n\n  const t = T[mode];\n\n  // ── sync mode from localStorage ────────────────────────────────────────────\n  useEffect(() => {\n    const saved = localStorage.getItem(\"kiro-mode\") as Mode | null;\n    if (saved) setMode(saved);\n    const handler = () => { const m = localStorage.getItem(\"kiro-mode\") as Mode|null; if (m) setMode(m); };\n    window.addEventListener(\"storage\", handler);\n    return () => window.removeEventListener(\"storage\", handler);\n  }, []);\n\n  // ── auto scroll ────────────────────────────────────────────────────────────\n  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior:\"smooth\" }); }, [messages]);\n\n  // ── load store greeting ────────────────────────────────────────────────────\n  useEffect(() => {\n    if (!storeId) return;\n    api.get(`/kai/greeting?storeId=${storeId}`)\n      .then(r => setStoreData(r.data?.data?.storeContext || r.data?.data))\n      .catch(() => {});\n  }, [storeId]);\n\n  // ── load conversation history ──────────────────────────────────────────────\n  useEffect(() => {\n    if (!initConvId) return;\n    api.get(`/kai/conversation/${initConvId}`)\n      .then(r => {\n        const msgs = (r.data?.data?.messages || []).map((m: any) => ({\n          id: m.id, role: m.role === \"user\" ? \"user\" : \"assistant\",\n          content: m.content, ts: m.createdAt, actions: m.actions || [],\n        }));\n        if (msgs.length) setMessages(msgs);\n      }).catch(() => {});\n  }, [initConvId]);\n\n  // ── keyboard shortcuts ─────────────────────────────────────────────────────\n  useEffect(() => {\n    const handler = (e: KeyboardEvent) => {\n      if ((e.metaKey||e.ctrlKey) && e.key===\"k\") { e.preventDefault(); setShowSearch(s=>!s); setTimeout(()=>searchRef.current?.focus(),80); }\n      if (e.key===\"Escape\") { setShowSearch(false); setSlashMenu(false); setEditingId(null); }\n    };\n    window.addEventListener(\"keydown\", handler);\n    return () => window.removeEventListener(\"keydown\", handler);\n  }, []);\n\n  // ── scroll-to-bottom detector ──────────────────────────────────────────────\n  useEffect(() => {\n    const el = msgListRef.current;\n    if (!el) return;\n    const handler = () => setShowScrollBtn(el.scrollHeight - el.scrollTop - el.clientHeight > 120);\n    el.addEventListener(\"scroll\", handler);\n    return () => el.removeEventListener(\"scroll\", handler);\n  }, []);\n\n  // ── smart follow-up suggestions after KIRO responds ───────────────────────\n  useEffect(() => {\n    const last = messages[messages.length-1];\n    if (!last || last.role !== \"assistant\" || last.streaming) { setSuggestions([]); return; }\n    const t = last.content.toLowerCase();\n    if (t.includes(\"product\") || t.includes(\"import\"))\n      setSuggestions([\"Write ad copy for this\",\"Set a price for it\",\"Find similar products\"]);\n    else if (t.includes(\"order\") || t.includes(\"fulfill\"))\n      setSuggestions([\"How do I contact the supplier?\",\"Mark as fulfilled\",\"Show pending orders\"]);\n    else if (t.includes(\"revenue\") || t.includes(\"sales\") || t.includes(\"analytics\"))\n      setSuggestions([\"What should I focus on today?\",\"Which products are top sellers?\",\"Create a flash sale\"]);\n    else if (t.includes(\"ad\") || t.includes(\"copy\") || t.includes(\"tiktok\"))\n      setSuggestions([\"Make a WhatsApp version\",\"Make it shorter\",\"Generate an image for it\"]);\n    else\n      setSuggestions([]);\n  }, [messages]);\n\n  // ── voice ──────────────────────────────────────────────────────────────────\n  const handleVoice = () => {\n    const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;\n    if (!SR) { toast.error(\"Voice works best in Chrome or Edge\"); return; }\n    if (listening) {\n      recogRef.current?.stop();\n      setListening(false);\n      setVoiceInterim(\"\");\n      return;\n    }\n    const r = new SR();\n    r.lang = \"en-NG\";\n    r.interimResults = true;\n    r.continuous = true;\n    r.onresult = (e: any) => {\n      let interim = \"\";\n      let final   = \"\";\n      for (let i = e.resultIndex; i < e.results.length; i++) {\n        const t = e.results[i][0].transcript;\n        if (e.results[i].isFinal) final += t;\n        else interim += t;\n      }\n      // Show live interim in the bubble\n      setVoiceInterim(interim);\n      // Append final text to input\n      if (final) setInput(prev => (prev ? prev + \" \" + final : final).trim());\n    };\n    r.onerror = (e: any) => {\n      if (e.error !== \"aborted\") toast.error(\"Voice error — try again\");\n      setListening(false);\n      setVoiceInterim(\"\");\n    };\n    r.onend = () => { setListening(false); setVoiceInterim(\"\"); };\n    r.start();\n    recogRef.current = r;\n    setListening(true);\n  };\n\n  // ── slash commands ────────────────────────────────────────────────────────\n  const SLASH_CMDS = [\n    // SALES\n    { cmd:\"/flash-sale\",  label:\"⚡ Run Flash Sale\",     prompt:\"Help me launch a flash sale right now. Suggest which products to discount based on inventory and sales velocity, then create the flash sale with optimal pricing.\" },\n    { cmd:\"/discount\",    label:\"🏷️ Create Discount\",    prompt:\"Create a smart discount code. Suggest a code name and discount percentage based on my margins.\" },\n    { cmd:\"/bogo\",        label:\"🎁 BOGO Offer\",          prompt:\"Set up a buy-one-get-one offer. Recommend which products to include for highest profit retention.\" },\n\n    // PRODUCTS\n    { cmd:\"/import\",      label:\"📥 Import Product\",      prompt:\"I want to import a product. Paste the URL:\" },\n    { cmd:\"/audit\",       label:\"🔍 Product Audit\",       prompt:\"Audit all my products. Find: 1) products with no images 2) products with no description 3) products with prices that look wrong 4) products with low inventory. Suggest fixes.\" },\n    { cmd:\"/rewrite\",     label:\"✏️ Rewrite Descriptions\", prompt:\"Review my products and identify which descriptions need improvement. For each, write a better version that converts Nigerian buyers.\" },\n    { cmd:\"/price-check\", label:\"💰 Price Audit\",         prompt:\"Audit my product prices. For each, tell me if it's too high, too low, or just right for the Nigerian market. Suggest specific price changes.\" },\n\n    // MARKETING\n    { cmd:\"/whatsapp\",    label:\"💬 WhatsApp Broadcast\",  prompt:\"Help me write a WhatsApp broadcast. Suggest the best message type right now (promo, restock, abandoned cart, win-back).\" },\n    { cmd:\"/email\",       label:\"📧 Email Campaign\",      prompt:\"Create an email campaign for my customers. Pick the best campaign type for right now and write the full email.\" },\n    { cmd:\"/abandoned\",   label:\"🛒 Recover Carts\",       prompt:\"Check my abandoned carts. Show how many, total value at risk, and send recovery messages.\" },\n    { cmd:\"/instagram\",   label:\"📸 Instagram Caption\",   prompt:\"Write me an Instagram caption with Nigerian hashtags for:\" },\n    { cmd:\"/tiktok\",      label:\"🎬 TikTok Script\",       prompt:\"Write a viral TikTok script for Nigerian audience. Hook in 3 seconds, fast cuts, CTA. Product:\" },\n    { cmd:\"/ad\",          label:\"📢 Ad Copy\",             prompt:\"Write high-converting Facebook/Instagram ad copy for my top product.\" },\n\n    // ANALYTICS\n    { cmd:\"/insights\",    label:\"📊 Store Insights\",      prompt:\"Give me a complete insights report on my store right now: top performers, what needs attention, what's growing, what's dying, and 3 specific actions I should take today.\" },\n    { cmd:\"/trending\",    label:\"🔥 Trending Products\",   prompt:\"Show me what's trending in Nigeria right now. Categories with high demand, products selling fast on Jumia/Konga/TikTok Shop, seasonal opportunities.\" },\n    { cmd:\"/forecast\",    label:\"📈 Sales Forecast\",      prompt:\"Forecast my sales for the next 30 days. Predicted revenue, predicted orders, what's likely to drive growth, what could slow it down.\" },\n    { cmd:\"/plan\",        label:\"🚀 Growth Plan\",         prompt:\"Give me a 5-step plan to grow my store this month, specific to my current situation.\" },\n\n    // OPERATIONS\n    { cmd:\"/fulfill\",     label:\"📦 Fulfill Orders\",      prompt:\"Show me all unfulfilled orders. For each, prepare the fulfillment. I'll approve and you process.\" },\n    { cmd:\"/refund\",      label:\"↩️ Process Refund\",     prompt:\"Help me process a refund. Order ID or customer name:\" },\n    { cmd:\"/stock\",       label:\"📋 Stock Check\",         prompt:\"Check my inventory. Show low stock, items needing reorder, and overstocked items. Suggest restock actions.\" },\n    { cmd:\"/orders\",      label:\"📑 Pending Orders\",      prompt:\"Show me all pending orders that need action.\" },\n    { cmd:\"/research\",    label:\"🌍 Market Research\",     prompt:\"What products are trending in my market this week?\" },\n  ];\n\n  // ── file upload ────────────────────────────────────────────────────────────\n  const handleFile = async (file: File) => {\n    if (file.size > 20 * 1024 * 1024) { toast.error(\"Max 20MB\"); return; }\n    setUploading(true);\n    try {\n      const dataUrl = await new Promise<string>((res, rej) => {\n        const r = new FileReader(); r.onload=()=>res(r.result as string); r.onerror=rej; r.readAsDataURL(file);\n      });\n      const isImage = file.type.startsWith(\"image/\");\n      const isPDF   = file.type === \"application/pdf\";\n      setAttach({ url: isImage ? dataUrl : undefined, base64: isPDF ? dataUrl.split(\",\")[1] : undefined, type: isImage ? \"image\" : isPDF ? \"pdf\" : \"csv\", name: file.name, size: file.size });\n    } catch { toast.error(\"Upload failed\"); } finally { setUploading(false); }\n  };\n\n  // ── image generation ───────────────────────────────────────────────────────\n  const generateImage = useCallback((prompt: string) => {\n    const kid = `k${Date.now()}`;\n    const clean = prompt.replace(/^(generate|create|make|draw)\\s+(a[n]?\\s+)?(image|photo|picture|visual)\\s+(of\\s+|for\\s+)?/i,\"\").trim();\n    const encoded = encodeURIComponent(`${clean}, product photography, clean background, professional, high quality`);\n    const url = `https://image.pollinations.ai/prompt/${encoded}?width=768&height=768&seed=${Math.random()*9999|0}&nologo=true&model=flux`;\n    setMessages(p => [...p, { id:kid, role:\"assistant\", content:`Generating image for \"${clean}\"…`, streaming:true, ts:new Date().toISOString() }]);\n    const img = new Image();\n    img.onload  = () => setMessages(p => p.map(m => m.id===kid ? { ...m, streaming:false, content:`Here's your image.`, imageUrl:url } : m));\n    img.onerror = () => setMessages(p => p.map(m => m.id===kid ? { ...m, streaming:false, content:\"Image generation unavailable. Try describing the product to me instead.\" } : m));\n    img.src = url;\n  }, []);\n\n  // ── send ───────────────────────────────────────────────────────────────────\n  const send = useCallback(async (override?: string) => {\n    const text = (override || input).trim();\n    if ((!text && !attach) || loading || !storeId) return;\n\n    // Image gen intercept\n    if (text && /^(generate|create|make|draw|show)\\s+(a[n]?\\s+)?(image|photo|picture|visual)/i.test(text) && !attach) {\n      setMessages(p => [...p, { id:`u${Date.now()}`, role:\"user\", content:text, ts:new Date().toISOString() }]);\n      if (!override) setInput(\"\");\n      generateImage(text);\n      return;\n    }\n\n    const userMsg: Msg = { id:`u${Date.now()}`, role:\"user\", content: text || (attach ? `📎 ${attach.name}` : \"\"), imageUrl: attach?.type===\"image\" ? attach.url : undefined, ts:new Date().toISOString() };\n    const kiroId = `k${Date.now()}`;\n    const kiroMsg: Msg = { id:kiroId, role:\"assistant\", content:\"\", streaming:true, ts:new Date().toISOString() };\n\n    // Fire onFirstMessage so parent can title the session properly\n    if (messages.length === 0 && onFirstMessage) {\n      onFirstMessage(text || (attach?.name ? `📎 ${attach.name}` : 'New conversation'));\n    }\n\n    setMessages(p => [...p, userMsg, kiroMsg]);\n    if (!override) setInput(\"\");\n    setAttach(null);\n    setLoading(true);\n\n    abortRef.current?.abort();\n    abortRef.current = new AbortController();\n\n    try {\n      const body: any = { message: text || \"\", storeId, conversationId: convId || undefined };\n      if (attach?.type === \"image\" && attach.url?.startsWith(\"data:\")) {\n        body.imageBase64    = attach.url.split(\",\")[1];\n        body.imageMediaType = attach.url.split(\":\")[1]?.split(\";\")[0] || \"image/jpeg\";\n        body.imageUrl       = attach.url;\n      } else if (attach?.url) body.imageUrl = attach.url;\n      if (attach?.base64) { body.fileBase64 = attach.base64; body.fileType = attach.type; }\n      if (attach?.name)   body.fileName = attach.name;\n\n      const res = await fetch(`${BASE}/kai/smart-chat`, {\n        method: \"POST\",\n        headers: { \"Content-Type\":\"application/json\", ...(token ? { Authorization:`Bearer ${token}` } : {}) },\n        body: JSON.stringify(body),\n        signal: abortRef.current.signal,\n      });\n\n      if (!res.ok) {\n        const d = await res.json().catch(()=>({}));\n        if (res.status === 429 || d?.code === \"RATE_LIMIT\") { setRateLimit(true); return; }\n        throw new Error(d?.message || \"Request failed\");\n      }\n\n      const reader = res.body!.getReader();\n      const dec = new TextDecoder();\n      let full = \"\";\n      let newConvId = \"\";\n\n      while (true) {\n        const { done, value } = await reader.read();\n        if (done) break;\n        for (const line of dec.decode(value,{stream:true}).split(\"\\n\").filter(l=>l.startsWith(\"data: \"))) {\n          try {\n            const p = JSON.parse(line.slice(6));\n            if (p.token) { full += p.token; setMessages(m => m.map(x => x.id===kiroId ? {...x,content:full} : x)); }\n            if (p.conversationId && !convId) newConvId = p.conversationId;\n            if (p.actions?.length) setMessages(m => m.map(x => x.id===kiroId ? {...x, actions:[...(x.actions||[]),...p.actions].filter((a,i,arr)=>arr.findIndex(b=>b.type===a.type)===i)} : x));\n            if (p.done) {\n              if (newConvId) { setConvId(newConvId); onConversationCreated?.(newConvId); }\n              // Parse any inline actions from text\n              const inlineActions = parseActions(full);\n              setMessages(m => m.map(x => x.id===kiroId ? {\n                ...x, streaming:false,\n                actions: [...(x.actions||[]), ...inlineActions].filter((a,i,arr)=>arr.findIndex(b=>b.type===a.type)===i),\n              } : x));\n            }\n          } catch {}\n        }\n      }\n    } catch (err: any) {\n      if (err.name === \"AbortError\") return;\n      setMessages(m => m.map(x => x.id===kiroId ? {...x, streaming:false, content:\"Something went wrong. Check your connection and try again.\" } : x));\n    } finally { setLoading(false); }\n  }, [input, attach, loading, storeId, convId, token, generateImage, onConversationCreated]);\n\n  // ── action handlers ────────────────────────────────────────────────────────\n  const handleApprove = async (action: Action) => {\n    try {\n      const r = await api.post(\"/kai/action\", { storeId, actions:[{...action,approved:true}] });\n      const result = r.data?.results?.[0];\n      if (result?.success) toast.success(result.message || \"Done!\");\n      else if (result?.healedAction) {\n        toast.loading(\"Auto-fixing…\", {id:\"heal\"});\n        const r2 = await api.post(\"/kai/action\",{storeId,actions:[{...result.healedAction,approved:true}]});\n        const r2res = r2.data?.results?.[0];\n        if (r2res?.success) toast.success(r2res.message||\"Fixed and done!\",{id:\"heal\"});\n        else toast.error(result?.message||\"Action failed\",{id:\"heal\"});\n      } else toast.error(result?.message||\"Action failed\");\n    } catch (e: any) { toast.error(e.response?.data?.message||\"Failed\"); }\n  };\n\n  const handleRate = (id: string, v: \"up\"|\"down\") => {\n    setMessages(m => m.map(x => x.id===id ? {...x,thumbs:v} : x));\n  };\n\n  const handleRegen = async (id: string) => {\n    const idx = messages.findIndex(m => m.id===id);\n    if (idx < 1) return;\n    const prev = messages.slice(0,idx).reverse().find(m=>m.role===\"user\");\n    if (prev) { setMessages(m=>m.filter((_,i)=>i<idx)); send(prev.content); }\n  };\n\n  // ── render ─────────────────────────────────────────────────────────────────\n  return (\n    <div style={{ display:\"flex\", flexDirection:\"column\", height:\"100%\", minHeight:0, background: t.bg, fontFamily:\"'Inter',system-ui,sans-serif\", overflow:\"hidden\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');\n        @keyframes ks { to { transform: rotate(360deg); } }\n        @keyframes voiceBar { 0%,100%{transform:scaleY(1);opacity:.5} 50%{transform:scaleY(2);opacity:1} }\n        * { box-sizing: border-box; }\n        ::-webkit-scrollbar { width: 4px; }\n        ::-webkit-scrollbar-thumb { background: ${t.scrollbar}; border-radius: 2px; }\n      `}</style>\n\n      {/* Rate limit screen */}\n      {rateLimit ? (\n        <div style={{ flex:1, minHeight:0, display:\"flex\", flexDirection:\"column\", alignItems:\"center\", justifyContent:\"center\", padding:32, textAlign:\"center\" }}>\n          <div style={{ fontSize:48, marginBottom:16 }}>🔥</div>\n          <h2 style={{ fontSize:20, fontWeight:700, color:t.text, margin:\"0 0 8px\" }}>You've hit your limit</h2>\n          <p style={{ fontSize:14, color:t.sub, margin:\"0 0 20px\", maxWidth:280, lineHeight:1.6 }}>\n            Free accounts get 5 KIRO sessions per month. Upgrade to keep going.\n          </p>\n          <button onClick={()=>window.open(\"/dashboard/billing\",\"_blank\")}\n            style={{ padding:\"11px 24px\", borderRadius:10, border:\"none\", background:`linear-gradient(135deg,${t.accent},${t.accentD})`, color:\"#fff\", fontSize:14, fontWeight:600, cursor:\"pointer\" }}>\n            Unlock more sessions\n          </button>\n          <p style={{ fontSize:11, color:t.muted, margin:\"12px 0 0\" }}>Resets on the 1st of every month</p>\n        </div>\n      ) : (\n        <>\n          {/* ── Search bar ── */}\n          {showSearch && (\n            <div style={{ padding:\"8px 14px\", borderBottom:`1px solid ${t.border}`, background:t.surface, display:\"flex\", alignItems:\"center\", gap:8, flexShrink:0 }}>\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={t.muted} strokeWidth=\"2\" strokeLinecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.35-4.35\"/></svg>\n              <input ref={searchRef} value={searchQuery} onChange={e=>setSearchQuery(e.target.value)}\n                placeholder=\"Search conversation…\"\n                style={{ flex:1, background:\"transparent\", border:\"none\", outline:\"none\", fontSize:13, color:t.text, fontFamily:\"inherit\" }}/>\n              {searchQuery && <button onClick={()=>setSearchQuery(\"\")} style={{ background:\"none\", border:\"none\", color:t.muted, cursor:\"pointer\", fontSize:12 }}>✕</button>}\n              <button onClick={()=>{setShowSearch(false);setSearchQuery(\"\");}} style={{ background:\"none\", border:\"none\", color:t.muted, cursor:\"pointer\", fontSize:11 }}>Close</button>\n            </div>\n          )}\n\n          {/* ── Pinned messages panel ── */}\n          {showPinned && pinnedMsgs.length > 0 && (\n            <div style={{ padding:\"10px 14px\", borderBottom:`1px solid ${t.border}`, background:t.surface, maxHeight:140, overflowY:\"auto\", flexShrink:0 }}>\n              <p style={{ fontSize:11, fontWeight:700, color:t.muted, marginBottom:6, textTransform:\"uppercase\", letterSpacing:\"0.07em\" }}>📌 Pinned</p>\n              {messages.filter(m=>pinnedMsgs.includes(m.id)).map(m=>(\n                <div key={m.id} style={{ fontSize:12, color:t.text, padding:\"5px 0\", borderBottom:`1px solid ${t.border}`, lineHeight:1.5 }}>\n                  {cleanText(m.content).slice(0,120)}{m.content.length>120?\"…\":\"\"}\n                </div>\n              ))}\n            </div>\n          )}\n\n          {/* Messages */}\n          <div ref={msgListRef} style={{ flex:1, overflowY:\"auto\", padding:\"20px 16px\", minHeight:0, position:\"relative\" }}>\n            {messages.length === 0 ? (\n              <Welcome name={user?.name||\"there\"} storeData={storeData} onSend={send} t={t}/>\n            ) : (\n              messages\n                .filter(m => !searchQuery || m.content.toLowerCase().includes(searchQuery.toLowerCase()))\n                .map(msg => (\n                <MsgBubble key={msg.id} msg={msg} onApprove={handleApprove}\n                  onDismiss={a=>setMessages(m=>m.map(x=>({...x,actions:(x.actions||[]).filter(b=>b!==a)})))}\n                  onRate={handleRate} onRegen={handleRegen}\n                  onPin={(id)=>setPinnedMsgs(p=>p.includes(id)?p.filter(x=>x!==id):[...p,id])}\n                  isPinned={pinnedMsgs.includes(msg.id)}\n                  onEdit={(id,txt)=>{setEditingId(id);setEditText(txt);inputRef.current?.focus();}}\n                  t={t}/>\n              ))\n            )}\n            <div ref={bottomRef}/>\n          </div>\n\n          {/* ── Scroll to bottom ── */}\n          {showScrollBtn && (\n            <button onClick={()=>bottomRef.current?.scrollIntoView({behavior:\"smooth\"})}\n              style={{ position:\"absolute\", bottom:80, right:18, width:32, height:32, borderRadius:\"50%\", border:`1px solid ${t.border}`, background:t.surface, boxShadow:\"0 2px 10px rgba(0,0,0,0.12)\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", zIndex:10, color:t.sub }}>\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\"><path d=\"M12 5v14M5 12l7 7 7-7\"/></svg>\n            </button>\n          )}\n\n          {/* ── Smart follow-up suggestions ── */}\n          {suggestions.length > 0 && !loading && (\n            <div style={{ padding:\"8px 14px 4px\", display:\"flex\", gap:6, flexWrap:\"wrap\", flexShrink:0 }}>\n              {suggestions.map(s=>(\n                <button key={s} onClick={()=>{setInput(s);inputRef.current?.focus();}}\n                  style={{ padding:\"5px 11px\", borderRadius:99, border:`1px solid ${t.border}`, background:t.surface, color:t.sub, fontSize:12, cursor:\"pointer\", fontFamily:\"inherit\", transition:\"all 0.15s\", whiteSpace:\"nowrap\" }}\n                  onMouseEnter={e=>{e.currentTarget.style.borderColor=t.accent;e.currentTarget.style.color=t.accent;}}\n                  onMouseLeave={e=>{e.currentTarget.style.borderColor=t.border;e.currentTarget.style.color=t.sub;}}>\n                  {s}\n                </button>\n              ))}\n            </div>\n          )}\n\n          {/* Stop bar */}\n          {loading && (\n            <div style={{ padding:\"8px 16px\", borderTop:`1px solid ${t.border}`, background:t.surface, display:\"flex\", alignItems:\"center\", gap:10, flexShrink:0 }}>\n              <Spinner size={14} color={t.accent}/>\n              <span style={{ fontSize:12, color:t.sub, flex:1 }}>KIRO is thinking</span>\n              <button onClick={()=>abortRef.current?.abort()}\n                style={{ padding:\"4px 12px\", borderRadius:7, border:`1px solid ${t.border}`, background:\"transparent\", color:t.red, fontSize:12, cursor:\"pointer\" }}>\n                ⏹ Stop\n              </button>\n            </div>\n          )}\n\n          {/* Attachment chip */}\n          <AnimatePresence>\n            {attach && (\n              <motion.div initial={{height:0,opacity:0}} animate={{height:\"auto\",opacity:1}} exit={{height:0,opacity:0}}\n                style={{ padding:\"6px 14px\", borderTop:`1px solid ${t.border}`, background:t.surface, display:\"flex\", alignItems:\"center\", gap:8, flexShrink:0 }}>\n                {attach.type===\"image\" && attach.url && (\n                  <img src={attach.url} alt=\"\" style={{ width:32, height:32, borderRadius:6, objectFit:\"cover\" }}/>\n                )}\n                {attach.type!==\"image\" && <span style={{ fontSize:18 }}>{attach.type===\"pdf\"?\"📄\":\"📊\"}</span>}\n                <span style={{ fontSize:12, color:t.sub, flex:1, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{attach.name}</span>\n                <button onClick={()=>setAttach(null)} style={{ width:20, height:20, borderRadius:\"50%\", border:\"none\", background:t.elevated, color:t.sub, cursor:\"pointer\", fontSize:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>×</button>\n              </motion.div>\n            )}\n          </AnimatePresence>\n\n          {/* ── Slash command menu ── */}\n          {slashMenu && (\n            <div style={{ padding:\"6px 10px\", borderTop:`1px solid ${t.border}`, background:t.surface, display:\"flex\", flexDirection:\"column\", gap:2, flexShrink:0 }}>\n              {SLASH_CMDS.filter(c=>input===\"/\" || c.cmd.includes(input)).map(c=>(\n                <button key={c.cmd} onClick={()=>{setInput(c.prompt);setSlashMenu(false);inputRef.current?.focus();}}\n                  style={{ display:\"flex\", alignItems:\"center\", gap:10, padding:\"7px 10px\", borderRadius:8, border:\"none\", background:\"transparent\", cursor:\"pointer\", textAlign:\"left\", fontFamily:\"inherit\" }}\n                  onMouseEnter={e=>(e.currentTarget.style.background=t.elevated)}\n                  onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n                  <span style={{ fontSize:11, fontWeight:700, color:t.accent, minWidth:80, fontFamily:\"monospace\" }}>{c.cmd}</span>\n                  <span style={{ fontSize:12, color:t.sub }}>{c.label}</span>\n                </button>\n              ))}\n            </div>\n          )}\n\n          {/* ── Edit mode banner ── */}\n          {editingId && (\n            <div style={{ padding:\"6px 14px\", borderTop:`1px solid ${t.border}`, background:`${t.accent}10`, display:\"flex\", alignItems:\"center\", gap:8, flexShrink:0 }}>\n              <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={t.accent} strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\"/></svg>\n              <span style={{ fontSize:12, color:t.accent, flex:1 }}>Editing message</span>\n              <button onClick={()=>{setEditingId(null);setEditText(\"\");setInput(\"\");}} style={{ background:\"none\", border:\"none\", color:t.muted, cursor:\"pointer\", fontSize:11 }}>Cancel</button>\n              <button onClick={()=>{\n                setMessages(m=>m.map(x=>x.id===editingId?{...x,content:input}:x));\n                setEditingId(null); setEditText(\"\"); setInput(\"\");\n              }} style={{ background:t.accent, border:\"none\", color:\"#fff\", cursor:\"pointer\", fontSize:11, padding:\"3px 10px\", borderRadius:6, fontFamily:\"inherit\" }}>Save</button>\n            </div>\n          )}\n\n          {/* Input */}\n          <div style={{ padding:\"10px 14px 14px\", borderTop:`1px solid ${t.border}`, background:t.surface, flexShrink:0 }}>\n            <div style={{ borderRadius:14, border:`1px solid ${t.border}`, background:t.bg, overflow:\"hidden\", boxShadow:t.shadow, transition:\"border-color 0.15s, box-shadow 0.15s\" }}\n              onFocusCapture={e=>{(e.currentTarget as HTMLDivElement).style.borderColor=t.accent;(e.currentTarget as HTMLDivElement).style.boxShadow=`0 0 0 3px ${t.accentBg}`;}}\n              onBlurCapture={e=>{(e.currentTarget as HTMLDivElement).style.borderColor=t.border;(e.currentTarget as HTMLDivElement).style.boxShadow=t.shadow;}}>\n\n              <textarea ref={inputRef} value={input}\n                onChange={e=>{\n                  const v = e.target.value;\n                  setInput(v);\n                  e.target.style.height=\"auto\";\n                  e.target.style.height=Math.min(e.target.scrollHeight,160)+\"px\";\n                  setSlashMenu(v.startsWith(\"/\") && v.length <= 12);\n                  if (editingId) setEditText(v);\n                }}\n                onKeyDown={e=>{ if(e.key===\"Enter\"&&!e.shiftKey){e.preventDefault();send();} }}\n                onPaste={e=>{ const f=e.clipboardData.files?.[0]; if(f){handleFile(f);} }}\n                placeholder=\"Message KIRO… paste a URL, describe a product, or ask anything\"\n                rows={1} style={{ width:\"100%\", background:\"transparent\", border:\"none\", outline:\"none\", color:t.text, fontSize:14, lineHeight:1.6, resize:\"none\", padding:\"12px 14px 4px\", maxHeight:160, overflowY:\"auto\" }}/>\n\n              {/* Toolbar row */}\n              <div style={{ display:\"flex\", alignItems:\"center\", gap:4, padding:\"4px 10px 8px\" }}>\n                {/* Image upload */}\n                <button onClick={()=>{ fileRef.current!.accept=\"image/*\"; fileRef.current?.click(); }} disabled={uploading} title=\"Upload image\"\n                  style={{ width:28, height:28, borderRadius:7, border:\"none\", background:\"transparent\", color:t.sub, cursor:\"pointer\", fontSize:15, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  {uploading ? <Spinner size={12} color={t.accent}/> : \"🖼\"}\n                </button>\n                {/* File upload */}\n                <button onClick={()=>{ fileRef.current!.accept=\"image/*,.pdf,.csv\"; fileRef.current?.click(); }} disabled={uploading} title=\"Attach file\"\n                  style={{ width:28, height:28, borderRadius:7, border:\"none\", background:\"transparent\", color:t.sub, cursor:\"pointer\", fontSize:15, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  📎\n                </button>\n                {/* Voice — animated bars + live transcript */}\n                <div style={{ position:\"relative\", display:\"flex\", alignItems:\"center\", gap:4 }}>\n                  {listening && voiceInterim && (\n                    <div style={{ position:\"absolute\", bottom:\"calc(100% + 8px)\", right:0, background:t.surface, border:`1px solid ${t.border}`, borderRadius:10, padding:\"7px 12px\", fontSize:12, color:t.text, whiteSpace:\"nowrap\", maxWidth:220, overflow:\"hidden\", textOverflow:\"ellipsis\", boxShadow:t.shadow, zIndex:20, pointerEvents:\"none\" }}>\n                      <span style={{ color:t.muted, fontSize:10, display:\"block\", marginBottom:2 }}>Listening…</span>\n                      {voiceInterim}\n                    </div>\n                  )}\n                  {listening && (\n                    <div style={{ display:\"flex\", alignItems:\"center\", gap:2 }}>\n                      {[0,1,2,3,4].map(i => (\n                        <div key={i} style={{ width:3, height:14, borderRadius:99, background:t.red, animation:`voiceBar 0.6s ease-in-out ${i*0.1}s infinite`, opacity:0.85 }}/>\n                      ))}\n                    </div>\n                  )}\n                  <button onClick={handleVoice} title={listening ? \"Stop recording\" : \"Voice input\"}\n                    style={{ width:30, height:30, borderRadius:8, border:`1px solid ${listening ? t.red : t.border}`, background:listening ? `${t.red}15` : \"transparent\", color:listening ? t.red : t.sub, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", transition:\"all 0.2s\", flexShrink:0 }}>\n                    {listening\n                      ? <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"/></svg>\n                      : <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z\"/><path d=\"M19 10v2a7 7 0 0 1-14 0v-2\"/><line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"23\"/><line x1=\"8\" y1=\"23\" x2=\"16\" y2=\"23\"/></svg>\n                    }\n                  </button>\n                </div>\n                {/* Search */}\n                <button onClick={()=>{setShowSearch(s=>!s);setTimeout(()=>searchRef.current?.focus(),80);}} title=\"Search chat (⌘K)\"\n                  style={{ width:28, height:28, borderRadius:7, border:\"none\", background:showSearch?`${t.accent}15`:\"transparent\", color:showSearch?t.accent:t.sub, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.35-4.35\"/></svg>\n                </button>\n                {/* Pinned */}\n                {pinnedMsgs.length > 0 && (\n                  <button onClick={()=>setShowPinned(p=>!p)} title=\"Pinned messages\"\n                    style={{ width:28, height:28, borderRadius:7, border:\"none\", background:showPinned?`${t.accent}15`:\"transparent\", color:showPinned?t.accent:t.sub, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", position:\"relative\" }}>\n                    <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z\"/></svg>\n                    <span style={{ position:\"absolute\", top:2, right:2, width:7, height:7, borderRadius:\"50%\", background:t.accent, fontSize:8, color:\"#fff\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>{pinnedMsgs.length}</span>\n                  </button>\n                )}\n                {/* Export */}\n                <button title=\"Export conversation\"\n                  onClick={()=>{\n                    const txt = messages.map(m=>`${m.role===\"user\"?\"You\":\"KIRO\"}: ${cleanText(m.content)}`).join(\"\\n\\n\");\n                    const blob = new Blob([txt],{type:\"text/plain\"});\n                    const a = document.createElement(\"a\"); a.href=URL.createObjectURL(blob); a.download=\"kiro-chat.txt\"; a.click();\n                  }}\n                  style={{ width:28, height:28, borderRadius:7, border:\"none\", background:\"transparent\", color:t.sub, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n                </button>\n                {/* Generate image */}\n                <button onClick={()=>input.trim()?generateImage(input.trim()):toast.error(\"Describe what to generate\")} title=\"Generate AI image\"\n                  style={{ padding:\"3px 8px\", borderRadius:6, border:`1px solid ${t.border}`, background:\"transparent\", color:t.accent, cursor:\"pointer\", fontSize:11, fontWeight:600 }}>\n                  ✨ Image\n                </button>\n\n                <div style={{ flex:1 }}/>\n\n                {input.length > 300 && (\n                  <span style={{ fontSize:10, color:t.muted }}>{input.length}</span>\n                )}\n\n                {/* Send / stop */}\n                <motion.button onClick={()=>loading?abortRef.current?.abort():send()} whileTap={{scale:0.9}}\n                  style={{ width:32, height:32, borderRadius:9, border:\"none\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", transition:\"all 0.18s\",\n                    background:loading?\"rgba(220,38,38,0.12)\":(input.trim()||attach)?`linear-gradient(135deg,${t.accent},${t.accentD})`:`${t.accent}18`,\n                    boxShadow:(input.trim()||attach)&&!loading?`0 2px 10px ${t.accent}35`:\"none\" }}>\n                  {loading\n                    ? <Spinner size={12} color={t.red}/>\n                    : <svg width={13} height={13} viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M22 2L11 13M22 2L15 22l-4-9-9-4 20-7z\" stroke={(input.trim()||attach)?\"#fff\":t.accent} strokeWidth={2} strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg>}\n                </motion.button>\n              </div>\n            </div>\n\n            <p style={{ fontSize:10, color:t.muted, textAlign:\"center\", margin:\"6px 0 0\" }}>\n              Powered by DropOS\n            </p>\n          </div>\n        </>\n      )}\n\n      <input ref={fileRef} type=\"file\" accept=\"image/*,.pdf,.csv\" style={{ display:\"none\" }}\n        onChange={e=>{ if(e.target.files?.[0]) handleFile(e.target.files[0]); e.target.value=\"\"; }}/>\n    </div>\n  );\n}\n","frontend/src/components/kai/OpportunityFeed.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { api } from \"../../lib/api\";\nimport {\n  TrendingUp, TrendingDown, Package, AlertTriangle, Gift, \n  Calendar, Users, ShoppingCart, Sparkles, ArrowRight, ChevronRight, Zap\n} from \"lucide-react\";\n\ninterface OpportunityFeedProps {\n  storeId: string;\n  isDark: boolean;\n  onAction?: (action: string, data: any) => void;\n}\n\nconst ICONS: Record<string, any> = {\n  high_demand:      TrendingUp,\n  price_decrease:   TrendingDown,\n  low_stock:        Package,\n  bundle:           Gift,\n  abandoned_value:  ShoppingCart,\n  win_back:         Users,\n  fraud_risk:       AlertTriangle,\n  seasonal:         Calendar,\n  viral_product:    Sparkles,\n  price_increase:   TrendingUp,\n};\n\nconst COLORS: Record<string, { bg: string; color: string; bdr: string }> = {\n  high:   { bg: \"rgba(124,58,237,0.08)\",  color: \"#A78BFA\", bdr: \"rgba(124,58,237,0.2)\" },\n  medium: { bg: \"rgba(96,165,250,0.08)\",  color: \"#60A5FA\", bdr: \"rgba(96,165,250,0.2)\" },\n  low:    { bg: \"rgba(156,163,175,0.08)\", color: \"#9CA3AF\", bdr: \"rgba(156,163,175,0.2)\" },\n};\n\nexport function OpportunityFeed({ storeId, isDark, onAction }: OpportunityFeedProps) {\n  const t = {\n    card:   isDark ? \"rgba(255,255,255,0.02)\" : \"rgba(15,5,32,0.02)\",\n    border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\" : \"rgba(19,13,46,0.5)\",\n  };\n\n  const [expanded, setExpanded] = useState<number | null>(null);\n\n  const { data: opps = [], isLoading } = useQuery({\n    queryKey: [\"opportunities\", storeId],\n    queryFn:  () => api.get(`/kai/opportunities?storeId=${storeId}`).then(r => r.data.data || []),\n    enabled:  !!storeId,\n    refetchInterval: 5 * 60 * 1000, // refetch every 5 minutes\n    staleTime: 2 * 60 * 1000,\n  });\n\n  if (isLoading || opps.length === 0) return null;\n\n  return (\n    <div style={{ marginBottom: 24 }}>\n      <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 12 }}>\n        <div style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n          <Zap size={14} style={{ color: \"#A78BFA\" }}/>\n          <h3 style={{ fontSize: 13, fontWeight: 700, color: t.text, margin: 0 }}>\n            KIRO Spotted {opps.length} Opportunit{opps.length === 1 ? \"y\" : \"ies\"}\n          </h3>\n        </div>\n        <span style={{ fontSize: 11, color: t.muted }}>Updated 5 min ago</span>\n      </div>\n\n      <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n        {opps.slice(0, 4).map((opp: any, i: number) => {\n          const Icon = ICONS[opp.type] || Sparkles;\n          const colors = COLORS[opp.severity] || COLORS.medium;\n          const isOpen = expanded === i;\n\n          return (\n            <motion.div key={i}\n              initial={{ opacity: 0, y: 8 }}\n              animate={{ opacity: 1, y: 0 }}\n              transition={{ delay: i * 0.05 }}\n              style={{\n                borderRadius: 14,\n                border: `1px solid ${colors.bdr}`,\n                background: colors.bg,\n                overflow: \"hidden\",\n                cursor: \"pointer\",\n              }}\n              onClick={() => setExpanded(isOpen ? null : i)}>\n              <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, padding: 14 }}>\n                <div style={{\n                  width: 32, height: 32, borderRadius: 10,\n                  background: `${colors.color}15`,\n                  display: \"flex\", alignItems: \"center\", justifyContent: \"center\",\n                  flexShrink: 0,\n                }}>\n                  <Icon size={15} style={{ color: colors.color }} />\n                </div>\n                <div style={{ flex: 1, minWidth: 0 }}>\n                  <p style={{ fontSize: 13, fontWeight: 700, color: t.text, margin: 0 }}>{opp.title}</p>\n                  {!isOpen && (\n                    <p style={{ fontSize: 11, color: t.muted, margin: \"2px 0 0\", overflow: \"hidden\", textOverflow: \"ellipsis\", whiteSpace: \"nowrap\" }}>\n                      {opp.message}\n                    </p>\n                  )}\n                </div>\n                <ChevronRight size={14} style={{ color: t.muted, transform: isOpen ? \"rotate(90deg)\" : \"rotate(0)\", transition: \"transform 0.2s\" }}/>\n              </div>\n\n              <AnimatePresence>\n                {isOpen && (\n                  <motion.div\n                    initial={{ height: 0, opacity: 0 }}\n                    animate={{ height: \"auto\", opacity: 1 }}\n                    exit={{ height: 0, opacity: 0 }}\n                    transition={{ duration: 0.2 }}\n                    style={{ overflow: \"hidden\" }}>\n                    <div style={{ padding: \"0 14px 14px 58px\" }}>\n                      <p style={{ fontSize: 12, color: t.muted, lineHeight: 1.5, marginBottom: 12 }}>\n                        {opp.message}\n                      </p>\n                      {opp.action && (\n                        <button\n                          onClick={(e) => { e.stopPropagation(); onAction?.(opp.action, opp.data); }}\n                          style={{\n                            display: \"flex\", alignItems: \"center\", gap: 6,\n                            padding: \"8px 14px\", borderRadius: 10,\n                            background: `linear-gradient(135deg, ${colors.color}, ${colors.color}cc)`,\n                            color: \"#fff\", border: \"none\", cursor: \"pointer\",\n                            fontSize: 12, fontWeight: 700, fontFamily: \"inherit\",\n                          }}>\n                          {opp.action}\n                          <ArrowRight size={11}/>\n                        </button>\n                      )}\n                    </div>\n                  </motion.div>\n                )}\n              </AnimatePresence>\n            </motion.div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/page.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport Link from \"next/link\";\nimport { useCurrency } from \"../../lib/currency\";\nimport {\n  TrendingUp, ShoppingCart, Users, Package, Zap,\n  ChevronRight, Store, Flame, Activity, ArrowUpRight,\n  AlertCircle, Clock, CheckCircle2, RefreshCw\n} from \"lucide-react\";\nimport { useTheme } from \"../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { api } from \"../../lib/api\";\nimport { OpportunityFeed } from \"../../components/kai/OpportunityFeed\";\n\nconst V = { v500: \"#6B35E8\", v400: \"#8B5CF6\", v300: \"#A78BFA\", cyan: \"#06B6D4\", green: \"#10B981\", amber: \"#F59E0B\", red: \"#EF4444\" };\n\nconst fmt = (n: number) => new Intl.NumberFormat(\"en-NG\", { style:\"currency\", currency:\"NGN\", maximumFractionDigits:0 }).format(n||0);\n\nfunction StatCard({ label, value, delta, color, icon: Icon, delay = 0 }: any) {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = { card: isDark ? \"#181230\" : \"#fff\", border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\", text: isDark ? \"#fff\" : \"#0D0918\", muted: isDark ? \"rgba(255,255,255,0.38)\" : \"rgba(13,9,24,0.45)\" };\n  return (\n    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay }}\n      style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n      <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 12 }}>\n        <div style={{ width: 36, height: 36, borderRadius: 10, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${color}18` }}>\n          <Icon size={16} color={color} />\n        </div>\n        {delta !== undefined && (\n          <span style={{ fontSize: 11, fontWeight: 700, color: delta >= 0 ? V.green : V.red, background: delta >= 0 ? \"rgba(16,185,129,0.1)\" : \"rgba(239,68,68,0.1)\", padding: \"3px 8px\", borderRadius: 99 }}>\n            {delta >= 0 ? \"+\" : \"\"}{delta}%\n          </span>\n        )}\n      </div>\n      <p style={{ fontSize: 22, fontWeight: 900, color: t.text, letterSpacing: \"-0.04em\", lineHeight: 1 }}>{value}</p>\n      <p style={{ fontSize: 12, color: t.muted, marginTop: 4 }}>{label}</p>\n    </motion.div>\n  );\n}\n\nfunction OrderRow({ order, t }: any) {\n  const statusColors: Record<string, string> = {\n    PENDING: V.amber, COMPLETED: V.green, SHIPPED: V.cyan,\n    DELIVERED: V.v400, CANCELLED: V.red, PROCESSING: V.cyan,\n  };\n  const color = statusColors[order.status] || V.amber;\n  return (\n    <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, padding: \"10px 0\", borderBottom: `1px solid ${t.border}` }}>\n      <div style={{ width: 32, height: 32, borderRadius: 8, background: `${color}15`, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}>\n        <ShoppingCart size={13} color={color} />\n      </div>\n      <div style={{ flex: 1, minWidth: 0 }}>\n        <p style={{ fontSize: 13, fontWeight: 600, color: t.text, whiteSpace: \"nowrap\", overflow: \"hidden\", textOverflow: \"ellipsis\" }}>\n          {order.customerName || \"Customer\"}\n        </p>\n        <p style={{ fontSize: 11, color: t.muted, marginTop: 1 }}>#{order.orderNumber || order.id?.slice(-6)}</p>\n      </div>\n      <div style={{ textAlign: \"right\", flexShrink: 0 }}>\n        <p style={{ fontSize: 13, fontWeight: 700, color: t.text }}>{fmt(order.total)}</p>\n        <span style={{ fontSize: 10, fontWeight: 700, color, background: `${color}15`, padding: \"2px 6px\", borderRadius: 99 }}>\n          {order.status}\n        </span>\n      </div>\n    </div>\n  );\n}\n\nexport default function DashboardPage() {\n  const { theme } = useTheme();\n  const { user } = useAuthStore();\n  const isDark = theme === \"dark\";\n  const [greeting, setGreeting] = useState(\"morning\");\n  const { fmt, code, symbol } = useCurrency();\n  const firstName = user?.name?.split(\" \")[0] || user?.email?.split(\"@\")[0] || \"there\";\n  const storeId = user?.stores?.[0]?.id;\n  const storeSlug = user?.stores?.[0]?.slug;\n\n  useEffect(() => {\n    const h = new Date().getHours();\n    setGreeting(h < 12 ? \"morning\" : h < 17 ? \"afternoon\" : \"evening\");\n  }, []);\n\n  const t = {\n    card:   isDark ? \"#181230\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\",\n    text:   isDark ? \"#fff\"    : \"#0D0918\",\n    muted:  isDark ? \"rgba(255,255,255,0.38)\" : \"rgba(13,9,24,0.45)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(15,5,32,0.02)\",\n  };\n\n  const { data: analytics } = useQuery({\n    queryKey: [\"dashboard-analytics\", storeId],\n    queryFn:  () => api.get(`/analytics/${storeId}?period=7`).then(r => r.data.data),\n    enabled:  !!storeId,\n    staleTime: 60000,\n  });\n\n  const { data: recentOrders } = useQuery({\n    queryKey: [\"dashboard-orders\", storeId],\n    queryFn:  () => api.get(`/orders/${storeId}?limit=5`).then(r => r.data.data?.orders || r.data.data || []),\n    enabled:  !!storeId,\n    staleTime: 30000,\n  });\n\n  const { data: pulse } = useQuery({\n    queryKey: [\"kiro-pulse\", storeId],\n    queryFn:  () => api.get(`/kai/pulse?storeId=${storeId}&limit=3`).then(r => r.data.data || []),\n    enabled:  !!storeId,\n    staleTime: 120000,\n  });\n\n  const stats = analytics?.stats || {};\n  const orders = Array.isArray(recentOrders) ? recentOrders : [];\n  // Deduplicate by type — keep most recent of each type, max 4\n  const seen = new Set<string>();\n  const alerts = (Array.isArray(pulse) ? pulse : [])\n    .filter((a: any) => { if (seen.has(a.type)) return false; seen.add(a.type); return true; })\n    .slice(0, 4);\n\n  const statCards = [\n    { label: \"Revenue (7d)\",  value: fmt(stats.revenue || 0),          delta: stats.revenueDelta,  color: V.v400,  icon: TrendingUp  },\n    { label: \"Orders (7d)\",   value: (stats.orders    || 0).toLocaleString(), delta: stats.ordersDelta, color: V.cyan,  icon: ShoppingCart },\n    { label: \"Customers\",     value: (stats.customers || 0).toLocaleString(), delta: undefined,         color: V.green, icon: Users        },\n    { label: \"Products\",      value: (stats.products  || 0).toLocaleString(), delta: undefined,         color: V.amber, icon: Package      },\n  ];\n\n  const quickActions = [\n    { label: \"Add Product\",  href: \"/dashboard/products\",   icon: Package,   color: V.v400  },\n    { label: \"View Store\",   href: storeSlug ? `/store/${storeSlug}` : \"/dashboard/stores\", icon: Store, color: V.cyan, target: \"_blank\" },\n    { label: \"Flash Sale\",   href: \"/dashboard/flash-sales\",icon: Flame,     color: V.amber },\n    { label: \"Analytics\",    href: \"/dashboard/analytics\",  icon: Activity,  color: V.green },\n  ];\n\n  return (\n    <div style={{ maxWidth: 1200, margin: \"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} style={{ marginBottom: 24 }}>\n        <h1 style={{ fontSize: 22, fontWeight: 900, letterSpacing: \"-0.04em\", color: t.text, marginBottom: 4 }}>\n          Good {greeting}, {firstName} 👋\n        </h1>\n        <p style={{ fontSize: 13, color: t.muted }}>\n          {user?.stores?.[0]?.name || \"Your store\"} · {new Date().toLocaleDateString(\"en-NG\", { weekday: \"long\", day: \"numeric\", month: \"long\" })}\n        </p>\n      </motion.div>\n\n      {/* Stats */}\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4,1fr)\", gap: 12, marginBottom: 20 }} className=\"grid-cols-2 sm:grid-cols-4\">\n        {statCards.map((s, i) => <StatCard key={s.label} {...s} delay={i * 0.07} />)}\n      </div>\n\n      <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 340px\", gap: 16 }} className=\"grid-1col lg:grid-2col\">\n        {/* Left: Recent Orders */}\n        <div>\n          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}`, marginBottom: 16 }}>\n            <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 14 }}>\n              <span style={{ fontSize: 13, fontWeight: 700, color: t.text }}>Recent Orders</span>\n              <Link href=\"/dashboard/orders\" style={{ display: \"flex\", alignItems: \"center\", gap: 4, fontSize: 12, color: V.v400, textDecoration: \"none\", fontWeight: 600 }}>\n                View all <ChevronRight size={13} />\n              </Link>\n            </div>\n            {orders.length === 0 ? (\n              <div style={{ textAlign: \"center\", padding: \"28px 0\" }}>\n                <ShoppingCart size={28} style={{ color: t.muted, margin: \"0 auto 8px\" }} />\n                <p style={{ fontSize: 12, color: t.muted }}>No orders yet. Share your store link to get your first sale.</p>\n                {storeSlug && (\n                  <a href={`/store/${storeSlug}`} target=\"_blank\" rel=\"noreferrer\"\n                    style={{ display: \"inline-flex\", alignItems: \"center\", gap: 6, marginTop: 12, fontSize: 12, fontWeight: 700, color: V.v400, textDecoration: \"none\", background: \"rgba(107,53,232,0.08)\", padding: \"6px 14px\", borderRadius: 99, border: \"1px solid rgba(107,53,232,0.2)\" }}>\n                    <Store size={11} /> View your store <ArrowUpRight size={11} />\n                  </a>\n                )}\n              </div>\n            ) : (\n              <div>\n                {orders.slice(0, 5).map((o: any) => <OrderRow key={o.id} order={o} t={t} />)}\n              </div>\n            )}\n          </motion.div>\n\n          {/* KIRO Opportunity Feed - proactive intelligence */}\n          {storeId && <OpportunityFeed storeId={storeId} isDark={isDark} onAction={(action) => {\n            // Trigger KIRO chat with the action\n            if (typeof window !== \"undefined\") {\n              window.dispatchEvent(new CustomEvent(\"kiro:execute\", { detail: { prompt: action } }));\n            }\n          }}/>}\n\n          {/* KIRO Pulse Alerts */}\n          {alerts.length > 0 && (\n            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}\n              style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n              <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 14 }}>\n                <Zap size={14} color={V.v400} />\n                <span style={{ fontSize: 13, fontWeight: 700, color: t.text }}>KIRO Alerts</span>\n              </div>\n              <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n                {alerts.map((a: any) => (\n                  <div key={a.id} style={{ display: \"flex\", gap: 10, padding: 10, borderRadius: 10, background: t.faint, border: `1px solid ${t.border}` }}>\n                    <AlertCircle size={13} color={a.severity === \"high\" ? V.red : V.amber} style={{ flexShrink: 0, marginTop: 1 }} />\n                    <div>\n                      <p style={{ fontSize: 12, fontWeight: 600, color: t.text }}>{a.title}</p>\n                      <p style={{ fontSize: 11, color: t.muted, marginTop: 2 }}>{a.message}</p>\n                    </div>\n                  </div>\n                ))}\n              </div>\n            </motion.div>\n          )}\n        </div>\n\n        {/* Right column */}\n        <div style={{ display: \"flex\", flexDirection: \"column\", gap: 14 }}>\n          {/* KIRO CTA */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.25 }}\n            style={{ padding: 18, borderRadius: 16, background: \"linear-gradient(135deg,#2D1B69,#1a0f3c)\", border: \"1px solid rgba(107,53,232,0.3)\", position: \"relative\", overflow: \"hidden\" }}>\n            <div style={{ position: \"absolute\", top: -20, right: -20, width: 80, height: 80, borderRadius: \"50%\", background: \"rgba(107,53,232,0.15)\" }} />\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 8 }}>\n              <div style={{ width: 28, height: 28, borderRadius: 8, background: \"rgba(107,53,232,0.3)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                <Zap size={13} color={V.v300} />\n              </div>\n              <span style={{ fontSize: 12, fontWeight: 700, color: V.v300 }}>KIRO</span>\n            </div>\n            <p style={{ fontSize: 13, fontWeight: 700, color: \"#fff\", marginBottom: 6 }}>What do you want to build today?</p>\n            <p style={{ fontSize: 11, color: \"rgba(255,255,255,0.5)\", marginBottom: 14, lineHeight: 1.5 }}>\n              Import products, write copy, run a sale, or just ask anything about your store.\n            </p>\n            <Link href=\"/kiro\">\n              <button style={{ width: \"100%\", padding: \"9px 0\", borderRadius: 10, border: \"none\", cursor: \"pointer\", background: \"rgba(107,53,232,0.4)\", color: \"#fff\", fontSize: 12, fontWeight: 700, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: 6 }}>\n                <Zap size={12} /> Chat with KIRO\n              </button>\n            </Link>\n          </motion.div>\n\n          {/* Quick Actions */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.32 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n            <span style={{ fontSize: 13, fontWeight: 700, color: t.text, display: \"block\", marginBottom: 12 }}>Quick Actions</span>\n            <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: 8 }}>\n              {quickActions.map(a => {\n                const Icon = a.icon;\n                return (\n                  <Link key={a.label} href={a.href} target={(a as any).target} style={{ textDecoration: \"none\" }}>\n                    <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.97 }}\n                      style={{ display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: 7, padding: 12, borderRadius: 12, cursor: \"pointer\", background: t.faint, border: `1px solid ${t.border}` }}>\n                      <div style={{ width: 30, height: 30, borderRadius: 9, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${a.color}15` }}>\n                        <Icon size={14} color={a.color} />\n                      </div>\n                      <span style={{ fontSize: 11, fontWeight: 600, color: t.muted, textAlign: \"center\" }}>{a.label}</span>\n                    </motion.div>\n                  </Link>\n                );\n              })}\n            </div>\n          </motion.div>\n\n          {/* Store status */}\n          <motion.div initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.38 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}` }}>\n            <span style={{ fontSize: 13, fontWeight: 700, color: t.text, display: \"block\", marginBottom: 12 }}>Store Status</span>\n            <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8 }}>\n              {[\n                { label: \"Store live\",      done: !!user?.stores?.[0]?.id,                         icon: Store        },\n                { label: \"Products added\",  done: (stats?.products || analytics?.totalProducts || 0) > 0, icon: Package      },\n                { label: \"First order\",     done: (stats?.orders   || analytics?.totalOrders    || orders.length || 0) > 0, icon: ShoppingCart },\n                { label: \"Payment setup\",   done: !!(user?.stores?.[0] as any)?.paystackPublicKey || !!(user?.stores?.[0] as any)?.currency, icon: CheckCircle2 },\n              ].map(item => {\n                const Icon = item.icon;\n                return (\n                  <div key={item.label} style={{ display: \"flex\", alignItems: \"center\", gap: 8 }}>\n                    <div style={{ width: 22, height: 22, borderRadius: 6, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: item.done ? \"rgba(16,185,129,0.1)\" : t.faint, flexShrink: 0 }}>\n                      <Icon size={11} color={item.done ? V.green : t.muted} />\n                    </div>\n                    <span style={{ fontSize: 12, color: item.done ? t.text : t.muted, flex: 1 }}>{item.label}</span>\n                    {item.done\n                      ? <CheckCircle2 size={13} color={V.green} />\n                      : <Clock size={13} style={{ color: t.muted }} />}\n                  </div>\n                );\n              })}\n            </div>\n          </motion.div>\n        </div>\n      </div>\n\n      <style>{`\n        @media(max-width:900px){\n          .grid-cols-2{grid-template-columns:1fr 1fr!important}\n          .grid-1col.lg\\\\:grid-2col{grid-template-columns:1fr!important}\n        }\n        @media(max-width:480px){\n          .grid-cols-2{grid-template-columns:1fr 1fr!important}\n        }\n      `}</style>\n    </div>\n  );\n}\n"};
for(const[rel,c]of Object.entries(files)){
  const p=rel.split('/').join(path.sep);
  fs.mkdirSync(path.dirname(p),{recursive:true});
  fs.writeFileSync(p,c,'utf8');
  console.log('✓',rel);
}
